import React, { useState, useMemo } from 'react';
import { useApp } from '../../context/AppContext';
import { Search, X, FileText, ShoppingCart, Users, Package, DollarSign, ArrowRight } from 'lucide-react';

export const GlobalSearchModal: React.FC = () => {
  const {
    isSearchOpen,
    setIsSearchOpen,
    requests,
    purchaseOrders,
    vendors,
    inventoryItems,
    invoices,
    rfqs,
    setActiveView,
    formatCurrency,
  } = useApp();

  const [query, setQuery] = useState('');

  const searchResults = useMemo(() => {
    if (!query.trim()) return [];
    const q = query.toLowerCase();

    const matchedReqs = requests
      .filter((r) => r.requestNumber.toLowerCase().includes(q) || r.title.toLowerCase().includes(q))
      .map((r) => ({
        id: r.id,
        title: `${r.requestNumber} - ${r.title}`,
        subtitle: `${r.departmentName || 'General'} • ${formatCurrency(r.estimatedBudget)}`,
        category: 'Requests',
        icon: FileText,
        view: 'requests' as const,
      }));

    const matchedPOs = purchaseOrders
      .filter((p) => p.poNumber.toLowerCase().includes(q) || p.vendorName.toLowerCase().includes(q))
      .map((p) => ({
        id: p.id,
        title: `${p.poNumber} (${p.vendorName})`,
        subtitle: `Total: ${formatCurrency(p.totalAmount)} • Status: ${p.status.replace('_', ' ')}`,
        category: 'Purchase Orders',
        icon: ShoppingCart,
        view: 'orders' as const,
      }));

    const matchedVendors = vendors
      .filter((v) => v.companyName.toLowerCase().includes(q) || v.categories.some((c) => c.toLowerCase().includes(q)))
      .map((v) => ({
        id: v.id,
        title: v.companyName,
        subtitle: `Rating: ${v.rating}★ • ${v.city} • Spend: ${formatCurrency(v.totalSpend)}`,
        category: 'Vendors',
        icon: Users,
        view: 'vendors' as const,
      }));

    const matchedInventory = inventoryItems
      .filter((i) => i.name.toLowerCase().includes(q) || i.sku.toLowerCase().includes(q))
      .map((i) => ({
        id: i.id,
        title: `${i.name} (${i.sku})`,
        subtitle: `Stock: ${i.currentStock} ${i.unit} in ${i.locationName}`,
        category: 'Inventory',
        icon: Package,
        view: 'inventory' as const,
      }));

    const matchedInvoices = invoices
      .filter((inv) => inv.invoiceNumber.toLowerCase().includes(q) || inv.vendorName.toLowerCase().includes(q))
      .map((inv) => ({
        id: inv.id,
        title: `${inv.invoiceNumber} (${inv.vendorName})`,
        subtitle: `Amount: ${formatCurrency(inv.totalAmount)} • Match: ${inv.threeWayMatch.isMatched ? 'Passed' : 'Exception'}`,
        category: 'Invoices',
        icon: DollarSign,
        view: 'finance' as const,
      }));

    return [...matchedReqs, ...matchedPOs, ...matchedVendors, ...matchedInventory, ...matchedInvoices].slice(0, 8);
  }, [query, requests, purchaseOrders, vendors, inventoryItems, invoices, rfqs, formatCurrency]);

  if (!isSearchOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/70 backdrop-blur-sm p-4 pt-16 sm:pt-24">
      <div className="relative w-full max-w-xl rounded-2xl bg-slate-900 border border-slate-800 shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-150">
        <div className="flex items-center px-4 py-3.5 border-b border-slate-800">
          <Search className="w-5 h-5 text-slate-400 mr-3 flex-shrink-0" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search requests, POs, suppliers, inventory, invoices..."
            className="w-full bg-transparent text-sm text-white placeholder-slate-400 focus:outline-none"
            autoFocus
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="p-1 text-slate-400 hover:text-white mr-1 text-xs"
            >
              Clear
            </button>
          )}
          <button
            onClick={() => setIsSearchOpen(false)}
            className="p-1 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Results */}
        <div className="max-h-96 overflow-y-auto p-2">
          {query.trim() === '' ? (
            <div className="p-6 text-center text-xs text-slate-400">
              Type keywords, request codes, vendor names, or inventory SKUs.
              <div className="flex flex-wrap justify-center gap-2 mt-3">
                <span className="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300">REQ-2026-089</span>
                <span className="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300">Nexus Logistics</span>
                <span className="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300">Nitrile Gloves</span>
                <span className="px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300">INV-2026-091</span>
              </div>
            </div>
          ) : searchResults.length === 0 ? (
            <div className="p-8 text-center text-xs text-slate-400">
              No matching procurement records found for "{query}".
            </div>
          ) : (
            <div className="space-y-1">
              {searchResults.map((item) => {
                const Icon = item.icon;
                return (
                  <button
                    key={`${item.category}-${item.id}`}
                    onClick={() => {
                      setActiveView(item.view);
                      setIsSearchOpen(false);
                    }}
                    className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-slate-800/80 transition text-left group"
                  >
                    <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-indigo-500/10 text-indigo-400 group-hover:bg-indigo-600 group-hover:text-white transition">
                        <Icon className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="text-xs font-semibold text-white">{item.title}</div>
                        <div className="text-[11px] text-slate-400">{item.subtitle}</div>
                      </div>
                    </div>
                    <div className="flex items-center gap-1.5 text-[11px] text-slate-400 group-hover:text-indigo-400">
                      <span>{item.category}</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>

        <div className="px-4 py-2.5 bg-slate-950/70 border-t border-slate-800 flex items-center justify-between text-[11px] text-slate-400">
          <span>Procura Universal Search Index</span>
          <span>ESC to close</span>
        </div>
      </div>
    </div>
  );
};

src/components/ai/AIAssistantModal.tsx:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import { Sparkles, X, Send, Bot, User as UserIcon, AlertTriangle, ShieldCheck } from 'lucide-react';

interface ChatMessage {
  id: string;
  sender: 'user' | 'assistant';
  text: string;
  timestamp: string;
  tableData?: Array<Record<string, string | number>>;
}

export const AIAssistantModal: React.FC = () => {
  const {
    isAiModalOpen,
    setIsAiModalOpen,
    requests,
    purchaseOrders,
    invoices,
    vendors,
    budgets,
    departments,
    currentUser,
    formatCurrency,
  } = useApp();

  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'm_welcome',
      sender: 'assistant',
      text: `Hello ${currentUser.name}! I am Procura Intelligence, your automated procurement advisor. I have real-time visibility into your requests, purchase orders, 3-way matching exceptions, supplier performance, and departmental budgets. How can I assist you today?`,
      timestamp: 'Just now',
    },
  ]);
  const [loading, setLoading] = useState(false);

  if (!isAiModalOpen) return null;

  const quickPrompts = [
    'Show me all pending approvals',
    'Which invoices are blocked or have exceptions?',
    'Show me overdue purchase orders',
    'Which suppliers have quality or delivery flags?',
    'What is our budget breakdown by department?',
  ];

  const handleSend = (queryText?: string) => {
    const query = (queryText || input).trim();
    if (!query) return;

    const userMsg: ChatMessage = {
      id: `usr_${Date.now()}`,
      sender: 'user',
      text: query,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    setTimeout(() => {
      let reply = '';
      const q = query.toLowerCase();

      if (q.includes('approval') || q.includes('pending')) {
        const pending = requests.filter((r) => r.status === 'pending_approval');
        if (pending.length > 0) {
          reply = `Found ${pending.length} request(s) awaiting approval:\n` +
            pending
              .map(
                (r) =>
                  `• **${r.requestNumber}** (${r.title}) — ${formatCurrency(r.estimatedBudget)} by ${r.requesterName} [${r.priority.toUpperCase()}]`
              )
              .join('\n') +
            `\n\nYou can review or authorize these directly in the Approvals Workspace.`;
        } else {
          reply = 'There are currently no procurement requests waiting in the approval queue.';
        }
      } else if (q.includes('blocked') || q.includes('exception') || q.includes('mismatch')) {
        const blockedInvoices = invoices.filter((i) => i.status === 'exception');
        reply =
          `Identified ${blockedInvoices.length} blocked invoice(s) due to Three-Way Match Discrepancies:\n\n` +
          blockedInvoices
            .map(
              (inv) =>
                `• **${inv.invoiceNumber}** from ${inv.vendorName} (${formatCurrency(inv.totalAmount)})\n  Reason: ${inv.threeWayMatch.discrepancyNote || 'Quantity / Price variance against GRN'}`
            )
            .join('\n\n') +
          `\n\nPayment has been locked to protect company capital until the credit note or vendor clarification is resolved.`;
      } else if (q.includes('overdue') || q.includes('late') || q.includes('delay')) {
        const overduePOs = purchaseOrders.filter(
          (p) => p.status === 'in_transit' && new Date(p.expectedDeliveryDate) < new Date()
        );
        if (overduePOs.length > 0) {
          reply =
            `Flagged ${overduePOs.length} overdue purchase order(s):\n\n` +
            overduePOs
              .map(
                (po) =>
                  `• **${po.poNumber}** — ${po.vendorName} (Due date was ${po.expectedDeliveryDate})\n  Items: ${po.items.map((i) => i.description).join(', ')}\n  Total: ${formatCurrency(po.totalAmount)}`
              )
              .join('\n\n') +
            `\n\nRecommendation: Send automated supplier reminder or apply SLA late delivery penalty clause.`;
        } else {
          reply = 'All active in-transit purchase orders are currently within their projected delivery windows.';
        }
      } else if (q.includes('supplier') || q.includes('vendor') || q.includes('risk')) {
        const risky = vendors.filter((v) => v.riskLevel === 'high' || v.riskLevel === 'medium');
        reply =
          `Supplier Risk Assessment Summary:\n\n` +
          risky
            .map(
              (v) =>
                `• **${v.companyName}** — Risk: **${v.riskLevel.toUpperCase()}**\n  On-time delivery: ${v.onTimeDeliveryRate}% | Quality: ${v.qualityScore}%\n  Issues: ${v.documents.some((d) => d.status === 'expired') ? 'Expired statutory tax document' : 'Late delivery frequency higher than benchmark'}`
            )
            .join('\n\n');
      } else if (q.includes('budget') || q.includes('department') || q.includes('spend')) {
        reply =
          `Current Departmental Budget Status:\n\n` +
          departments
            .map((d) => {
              const pct = Math.round((d.budgetSpent / d.budgetAllocated) * 100);
              return `• **${d.name} (${d.code})**\n  Allocated: ${formatCurrency(d.budgetAllocated)} | Spent: ${formatCurrency(d.budgetSpent)} (${pct}% utilized)`;
            })
            .join('\n\n');
      } else {
        reply = `I analyzed your active procurement records. We have ${requests.length} total procurement requests, ${purchaseOrders.length} purchase orders, ${vendors.length} enrolled suppliers, and ${invoices.length} active invoices. Let me know if you would like me to drill into a specific category, check compliance, or calculate cost variances.`;
      }

      setMessages((prev) => [
        ...prev,
        {
          id: `ast_${Date.now()}`,
          sender: 'assistant',
          text: reply,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        },
      ]);
      setLoading(false);
    }, 600);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 backdrop-blur-sm p-4">
      <div className="relative w-full max-w-2xl h-[620px] max-h-[90vh] rounded-2xl bg-slate-900 border border-slate-800 shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="p-4 sm:px-6 border-b border-slate-800 bg-slate-950/60 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-gradient-to-tr from-indigo-500 to-sky-400 text-white shadow-md shadow-indigo-500/20">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-bold text-white">Procura Intelligence Assistant</h3>
                <span className="px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-400 text-[10px] font-semibold flex items-center gap-1">
                  <ShieldCheck className="w-3 h-3" /> RBAC Enforced
                </span>
              </div>
              <p className="text-[11px] text-slate-400">Context-grounded AI procurement intelligence</p>
            </div>
          </div>
          <button
            onClick={() => setIsAiModalOpen(false)}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Quick prompt pills */}
        <div className="px-4 py-2 bg-slate-950/30 border-b border-slate-800/80 flex items-center gap-2 overflow-x-auto text-[11px]">
          <span className="text-slate-500 flex-shrink-0">Try asking:</span>
          {quickPrompts.map((p, idx) => (
            <button
              key={idx}
              onClick={() => handleSend(p)}
              className="flex-shrink-0 px-2.5 py-1 rounded-full bg-slate-800/90 hover:bg-indigo-600/30 hover:text-indigo-300 text-slate-300 border border-slate-700/60 transition"
            >
              {p}
            </button>
          ))}
        </div>

        {/* Chat Stream */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-4">
          {messages.map((m) => {
            const isMe = m.sender === 'user';
            return (
              <div key={m.id} className={`flex items-start gap-3 ${isMe ? 'flex-row-reverse' : ''}`}>
                <div
                  className={`w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 text-xs font-bold ${
                    isMe
                      ? 'bg-indigo-600 text-white'
                      : 'bg-slate-800 text-sky-400 border border-slate-700'
                  }`}
                >
                  {isMe ? <UserIcon className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
                </div>
                <div
                  className={`max-w-[80%] rounded-2xl p-4 text-xs leading-relaxed ${
                    isMe
                      ? 'bg-indigo-600 text-white rounded-tr-none'
                      : 'bg-slate-800/90 text-slate-200 border border-slate-700/60 rounded-tl-none whitespace-pre-line'
                  }`}
                >
                  {m.text}
                  <div
                    className={`text-[9px] mt-1.5 ${
                      isMe ? 'text-indigo-200 text-right' : 'text-slate-400'
                    }`}
                  >
                    {m.timestamp}
                  </div>
                </div>
              </div>
            );
          })}
          {loading && (
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-xl bg-slate-800 flex items-center justify-center text-sky-400 border border-slate-700">
                <Bot className="w-4 h-4 animate-spin" />
              </div>
              <div className="bg-slate-800/80 border border-slate-700/60 rounded-2xl rounded-tl-none p-3.5 text-xs text-slate-400 flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-sky-400 animate-ping" />
                Analyzing procurement records and budget rules...
              </div>
            </div>
          )}
        </div>

        {/* Input Bar */}
        <div className="p-3 sm:p-4 bg-slate-950 border-t border-slate-800">
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleSend();
            }}
            className="flex items-center gap-2"
          >
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask about spending, suppliers, approvals, or exceptions..."
              className="flex-1 bg-slate-900 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
            />
            <button
              type="submit"
              disabled={!input.trim()}
              className="p-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 disabled:opacity-40 text-white transition"
            >
              <Send className="w-4 h-4" />
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

src/components/onboarding/OnboardingWiza:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  ApprovalWorkflowType,
  BusinessType,
  CurrencyCode,
  SupportedLanguage,
  TeamSize,
} from '../../types';
import {
  Building2,
  Users,
  Layers,
  CheckCircle,
  FileSpreadsheet,
  Package,
  CreditCard,
  MapPin,
  Sparkles,
  ArrowRight,
  ArrowLeft,
  Briefcase,
  Store,
  User,
  Factory,
  HardHat,
  Stethoscope,
  GraduationCap,
  Globe2,
} from 'lucide-react';

export const OnboardingWizard: React.FC = () => {
  const { orgConfig, updateOrgConfig, setActiveView, loadPreset } = useApp();

  const [step, setStep] = useState(1);
  const totalSteps = 10;

  // Form states
  const [name, setName] = useState(orgConfig.name || 'My Organization');
  const [businessType, setBusinessType] = useState<BusinessType>(orgConfig.businessType);
  const [teamSize, setTeamSize] = useState<TeamSize>(orgConfig.teamSize);
  const [hasDepartments, setHasDepartments] = useState(orgConfig.hasDepartments);
  const [approvalWorkflow, setApprovalWorkflow] = useState<ApprovalWorkflowType>(orgConfig.approvalWorkflow);
  const [hasSuppliers, setHasSuppliers] = useState(orgConfig.hasSuppliers);
  const [hasRfqs, setHasRfqs] = useState(orgConfig.hasRfqs);
  const [hasBudgets, setHasBudgets] = useState(orgConfig.hasBudgets);
  const [hasPhysicalGoods, setHasPhysicalGoods] = useState(orgConfig.hasPhysicalGoods);
  const [hasInvoicesPayments, setHasInvoicesPayments] = useState(orgConfig.hasInvoicesPayments);
  const [hasMultipleLocations, setHasMultipleLocations] = useState(orgConfig.hasMultipleLocations);
  const [currency, setCurrency] = useState<CurrencyCode>(orgConfig.currency);
  const [language, setLanguage] = useState<SupportedLanguage>(orgConfig.language);

  const businessTypes: { type: BusinessType; label: string; icon: React.ElementType; desc: string }[] = [
    { type: 'individual', label: 'Individual / Freelancer', icon: User, desc: 'Solo operations, no bureaucracy' },
    { type: 'small_business', label: 'Small Business / Shop', icon: Store, desc: 'Nimble teams, direct orders' },
    { type: 'corporation', label: 'Corporation / Enterprise', icon: Building2, desc: 'Multi-tiered, advanced matrix' },
    { type: 'construction', label: 'Construction & Civil', icon: HardHat, desc: 'Material specs, heavy deliveries' },
    { type: 'healthcare', label: 'Hospital / Healthcare', icon: Stethoscope, desc: 'Consumables & clinical equipment' },
    { type: 'education', label: 'School / University', icon: GraduationCap, desc: 'Faculty grants & campus logistics' },
    { type: 'manufacturing', label: 'Manufacturing / Factory', icon: Factory, desc: 'Raw inventory & high throughput' },
    { type: 'services', label: 'Professional Services', icon: Briefcase, desc: 'Software, consulting, operational tools' },
  ];

  const handleFinish = () => {
    updateOrgConfig({
      name,
      businessType,
      teamSize,
      hasDepartments,
      approvalWorkflow,
      hasSuppliers,
      hasRfqs,
      hasBudgets,
      hasPhysicalGoods,
      hasInvoicesPayments,
      hasMultipleLocations,
      currency,
      language,
      onboardingCompleted: true,
    });
    setActiveView('dashboard');
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col justify-between p-4 sm:p-8">
      {/* Top Header */}
      <div className="max-w-4xl w-full mx-auto flex items-center justify-between py-2 border-b border-slate-800">
        <div className="flex items-center gap-2.5">
          <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-indigo-600 to-sky-400 flex items-center justify-center font-bold text-lg text-white shadow-md shadow-indigo-500/20">
            P
          </div>
          <div>
            <span className="font-extrabold text-white text-base tracking-tight">Procura</span>
            <span className="text-[10px] text-indigo-400 block -mt-1 font-semibold uppercase tracking-wider">
              Setup Wizard
            </span>
          </div>
        </div>

        {/* 1-Click Quick Presets for rapid evaluation */}
        <div className="hidden sm:flex items-center gap-1.5 text-xs">
          <span className="text-slate-400 mr-1 text-[11px]">Quick Presets:</span>
          <button
            onClick={() => loadPreset('individual')}
            className="px-2.5 py-1 rounded-lg bg-slate-900 border border-slate-700/80 hover:border-indigo-500 text-slate-300 transition text-[11px]"
          >
            Solo Freelancer
          </button>
          <button
            onClick={() => loadPreset('retail')}
            className="px-2.5 py-1 rounded-lg bg-slate-900 border border-slate-700/80 hover:border-indigo-500 text-slate-300 transition text-[11px]"
          >
            Retail Shop
          </button>
          <button
            onClick={() => loadPreset('enterprise')}
            className="px-2.5 py-1 rounded-lg bg-indigo-600/30 border border-indigo-500/50 hover:bg-indigo-600 text-indigo-200 transition text-[11px]"
          >
            Full Enterprise
          </button>
        </div>
      </div>

      {/* Main Wizard Card */}
      <div className="max-w-3xl w-full mx-auto my-8 bg-slate-900/90 border border-slate-800 rounded-3xl p-6 sm:p-10 shadow-2xl relative overflow-hidden">
        {/* Progress Bar */}
        <div className="mb-8">
          <div className="flex items-center justify-between text-xs text-slate-400 mb-2">
            <span className="font-medium text-indigo-400 uppercase tracking-wider text-[11px]">
              Step {step} of {totalSteps}
            </span>
            <span>{Math.round((step / totalSteps) * 100)}% Completed</span>
          </div>
          <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-indigo-500 to-sky-400 transition-all duration-300 rounded-full"
              style={{ width: `${(step / totalSteps) * 100}%` }}
            />
          </div>
        </div>

        {/* Step 1: Organization Type & Name */}
        {step === 1 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 1 — What are you?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Procura adapts its terminology, procurement workflows, and dashboard cards based on your industry.
              </p>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1.5">Organization / Business Name</label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. Apex Global, Metro Health, City Construction"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white placeholder-slate-600 focus:outline-none focus:border-indigo-500"
              />
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {businessTypes.map((b) => {
                const Icon = b.icon;
                const isSelected = businessType === b.type;
                return (
                  <button
                    key={b.type}
                    onClick={() => {
                      setBusinessType(b.type);
                      if (b.type === 'individual') {
                        setTeamSize('1');
                        setHasDepartments(false);
                        setApprovalWorkflow('none');
                        setHasMultipleLocations(false);
                      }
                    }}
                    className={`p-3.5 rounded-2xl border text-left transition flex flex-col justify-between ${
                      isSelected
                        ? 'border-indigo-500 bg-indigo-950/40 text-white shadow-lg shadow-indigo-500/10'
                        : 'border-slate-800 bg-slate-950/40 hover:bg-slate-800/50 text-slate-300'
                    }`}
                  >
                    <Icon className={`w-6 h-6 mb-2 ${isSelected ? 'text-indigo-400' : 'text-slate-400'}`} />
                    <div>
                      <div className="text-xs font-bold text-white">{b.label}</div>
                      <div className="text-[10px] text-slate-400 leading-tight mt-0.5">{b.desc}</div>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Step 2: Team Size */}
        {step === 2 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 2 — How many people will use Procura?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Whether you're operating solo or orchestrating 500+ employees across continents, Procura scales with you.
              </p>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {(['1', '2-5', '6-20', '21-100', '101-500', '500+'] as TeamSize[]).map((size) => (
                <button
                  key={size}
                  onClick={() => {
                    setTeamSize(size);
                    if (size === '1') {
                      setHasDepartments(false);
                      setApprovalWorkflow('none');
                    }
                  }}
                  className={`p-5 rounded-2xl border text-center transition ${
                    teamSize === size
                      ? 'border-indigo-500 bg-indigo-950/40 text-white font-bold'
                      : 'border-slate-800 bg-slate-950/40 hover:bg-slate-800/50 text-slate-300'
                  }`}
                >
                  <Users className="w-6 h-6 mx-auto mb-2 text-indigo-400" />
                  <div className="text-base font-bold">{size === '1' ? 'Just Me' : `${size} People`}</div>
                  <div className="text-[10px] text-slate-400 mt-1">
                    {size === '1'
                      ? 'No departmental overhead'
                      : size === '2-5'
                      ? 'Lean agile team'
                      : size === '6-20'
                      ? 'Growing business'
                      : 'Mid & large enterprise'}
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Step 3: Departments */}
        {step === 3 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 3 — Do you operate with departments?</h2>
              <p className="text-xs text-slate-400 mt-1">
                If No, Procura removes all department selectors, heads, and routing so your workflows stay clean.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasDepartments(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasDepartments
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">No Departments</div>
                <p className="text-xs text-slate-300 leading-relaxed">
                  All requests and spend are tracked at the organization level without departmental silos.
                </p>
              </button>

              <button
                onClick={() => setHasDepartments(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasDepartments
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Yes, We Have Departments</div>
                <p className="text-xs text-slate-300 leading-relaxed">
                  Enables department heads, departmental budget allocations, cost centers, and departmental approval rules.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 4: Approval Workflows */}
        {step === 4 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 4 — Do purchases require approval?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Configure your governance level: from zero approvals for solo operators to multi-level matrix checks.
              </p>
            </div>

            <div className="space-y-3">
              {[
                {
                  type: 'none' as ApprovalWorkflowType,
                  title: 'No Approval Required',
                  desc: 'Requesters directly issue purchase orders without waiting for management authorization.',
                },
                {
                  type: 'simple' as ApprovalWorkflowType,
                  title: 'Simple Approval (1-Level)',
                  desc: 'Every purchase request is routed to the business owner or designated manager for signoff.',
                },
                {
                  type: 'multi_level' as ApprovalWorkflowType,
                  title: 'Multiple Approval Levels',
                  desc: 'Sequential signoffs: Requester → Department Head → Finance Comptroller → Executive.',
                },
                {
                  type: 'configurable_matrix' as ApprovalWorkflowType,
                  title: 'Configurable Approval Matrix Rules',
                  desc: 'Rules driven by spend thresholds, categories, departmental budgets, and vendor risk levels.',
                },
              ].map((wf) => (
                <button
                  key={wf.type}
                  onClick={() => setApprovalWorkflow(wf.type)}
                  className={`w-full p-4 rounded-2xl border text-left transition flex items-start gap-4 ${
                    approvalWorkflow === wf.type
                      ? 'border-indigo-500 bg-indigo-950/40 text-white'
                      : 'border-slate-800 bg-slate-950/40 text-slate-400'
                  }`}
                >
                  <div
                    className={`p-2 rounded-xl mt-0.5 ${
                      approvalWorkflow === wf.type ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400'
                    }`}
                  >
                    <CheckCircle className="w-4 h-4" />
                  </div>
                  <div>
                    <div className="text-sm font-bold text-white">{wf.title}</div>
                    <div className="text-xs text-slate-300 mt-0.5">{wf.desc}</div>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Step 5: External Suppliers */}
        {step === 5 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 5 — Do you work with external suppliers?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Enable vendor directories, document expiry reminders, compliance verification, and performance scoring.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasSuppliers(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasSuppliers
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Yes, Manage External Suppliers</div>
                <p className="text-xs text-slate-300">
                  Enables Supplier Management Center, Vendor Scorecards, Tax Clearance tracking, and Marketplace.
                </p>
              </button>

              <button
                onClick={() => setHasSuppliers(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasSuppliers
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">No External Suppliers</div>
                <p className="text-xs text-slate-300">
                  Internal purchasing only without vendor registration or supplier portal.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 6: Requests for Quotations (RFQs) */}
        {step === 6 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 6 — Do you issue RFQs / Tender Bidding?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Invite multiple suppliers, set weighted criteria (Price 40%, Quality 25%, Delivery 20%), compare side-by-side.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasRfqs(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasRfqs
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Enable RFQs & Competitive Bidding</div>
                <p className="text-xs text-slate-300">
                  Includes tender publishing, vendor bidding portal, weighted evaluation matrix, and award generation.
                </p>
              </button>

              <button
                onClick={() => setHasRfqs(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasRfqs
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Direct Purchasing Only</div>
                <p className="text-xs text-slate-300">
                  Skip RFQs; issue Purchase Orders straight from approved requests or catalog items.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 7: Budgets */}
        {step === 7 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 7 — Do you manage budgets?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Track allocated vs committed (POs in flight) vs spent amounts with automatic warning thresholds.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasBudgets(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasBudgets
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Enable Budget Controls</div>
                <p className="text-xs text-slate-300">
                  Enforces budget limits before purchase approval, alerts when approaching 80%, and blocks overruns.
                </p>
              </button>

              <button
                onClick={() => setHasBudgets(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasBudgets
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">No Budget Restrictions</div>
                <p className="text-xs text-slate-300">
                  Purchases can be made without binding cost center budget allocations.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 8: Physical Goods & Inventory */}
        {step === 8 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 8 — Do you receive physical goods?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Goods receipts automatically increment inventory stock levels per location, log damaged goods, and trigger returns.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasPhysicalGoods(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasPhysicalGoods
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Yes, Physical Goods & Warehouses</div>
                <p className="text-xs text-slate-300">
                  Enables Delivery tracking, Goods Receipts (GRN), Automated Inventory incrementing, and Return logs.
                </p>
              </button>

              <button
                onClick={() => setHasPhysicalGoods(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasPhysicalGoods
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Services & Digital Assets Only</div>
                <p className="text-xs text-slate-300">
                  No warehouse inventory or physical delivery tracking required.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 9: Invoices, 3-Way Match & Payments */}
        {step === 9 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 9 — Do you manage invoices and payments?</h2>
              <p className="text-xs text-slate-400 mt-1">
                Automated Three-Way Matching engine (PO vs GRN vs Invoice) to prevent fraud, over-billing, and missing goods.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setHasInvoicesPayments(true)}
                className={`p-6 rounded-2xl border text-left transition ${
                  hasInvoicesPayments
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Enable Finance & 3-Way Matching</div>
                <p className="text-xs text-slate-300">
                  Full invoice inbox, automatic discrepancy checks, approval on hold, and payment settlement queue.
                </p>
              </button>

              <button
                onClick={() => setHasInvoicesPayments(false)}
                className={`p-6 rounded-2xl border text-left transition ${
                  !hasInvoicesPayments
                    ? 'border-indigo-500 bg-indigo-950/40 text-white'
                    : 'border-slate-800 bg-slate-950/40 text-slate-400'
                }`}
              >
                <div className="text-base font-bold text-white mb-1">Simple Purchasing Only</div>
                <p className="text-xs text-slate-300">
                  Invoicing and bank settlements handled externally in external accounting software.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 10: Multi-Location, Currency & Language */}
        {step === 10 && (
          <div className="space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-white tracking-tight">Step 10 — Locations, Currency & Language</h2>
              <p className="text-xs text-slate-400 mt-1">
                Final step: Configure multi-branch logistics, default operating currency, and system interface language.
              </p>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-2">Multiple Locations / Branches?</label>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    onClick={() => setHasMultipleLocations(true)}
                    className={`p-3 rounded-xl border text-xs font-semibold transition ${
                      hasMultipleLocations
                        ? 'border-indigo-500 bg-indigo-950/40 text-white'
                        : 'border-slate-800 bg-slate-950 text-slate-400'
                    }`}
                  >
                    Yes (HQ, Warehouses, Sites)
                  </button>
                  <button
                    onClick={() => setHasMultipleLocations(false)}
                    className={`p-3 rounded-xl border text-xs font-semibold transition ${
                      !hasMultipleLocations
                        ? 'border-indigo-500 bg-indigo-950/40 text-white'
                        : 'border-slate-800 bg-slate-950 text-slate-400'
                    }`}
                  >
                    Single Location
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Operating Currency</label>
                  <select
                    value={currency}
                    onChange={(e) => setCurrency(e.target.value as CurrencyCode)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-indigo-500"
                  >
                    <option value="USD">USD ($) - US Dollar</option>
                    <option value="NGN">NGN (₦) - Nigerian Naira</option>
                    <option value="EUR">EUR (€) - Euro</option>
                    <option value="GBP">GBP (£) - British Pound</option>
                    <option value="KES">KES (KSh) - Kenyan Shilling</option>
                    <option value="JPY">JPY (¥) - Japanese Yen</option>
                    <option value="AED">AED (AED) - UAE Dirham</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Interface Language</label>
                  <select
                    value={language}
                    onChange={(e) => setLanguage(e.target.value as SupportedLanguage)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-indigo-500"
                  >
                    <option value="en">English (Global)</option>
                    <option value="fr">Français (French)</option>
                    <option value="es">Español (Spanish)</option>
                    <option value="ha">Hausa (Naija / West Africa)</option>
                    <option value="sw">Kiswahili (East Africa)</option>
                    <option value="ar">العربية (Arabic)</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Wizard Footer Controls */}
        <div className="mt-8 pt-6 border-t border-slate-800 flex items-center justify-between">
          {step > 1 ? (
            <button
              onClick={() => setStep(step - 1)}
              className="flex items-center gap-2 px-4 py-2.5 rounded-xl border border-slate-800 hover:bg-slate-800 text-xs font-semibold text-slate-300 transition"
            >
              <ArrowLeft className="w-4 h-4" />
              <span>Back</span>
            </button>
          ) : (
            <div />
          )}

          {step < totalSteps ? (
            <button
              onClick={() => setStep(step + 1)}
              className="flex items-center gap-2 px-6 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-xs font-bold text-white shadow-lg shadow-indigo-500/20 transition"
            >
              <span>Continue</span>
              <ArrowRight className="w-4 h-4" />
            </button>
          ) : (
            <button
              onClick={handleFinish}
              className="flex items-center gap-2 px-7 py-3 rounded-xl bg-gradient-to-r from-indigo-600 to-sky-500 hover:from-indigo-500 hover:to-sky-400 text-xs font-bold text-white shadow-lg shadow-indigo-500/30 transition transform hover:scale-[1.02]"
            >
              <Sparkles className="w-4 h-4" />
              <span>Launch Procura Command Center</span>
            </button>
          )}
        </div>
      </div>

      {/* Footer Branding */}
      <div className="max-w-4xl w-full mx-auto text-center text-xs text-slate-400 py-2">
        Procura Universal Procurement OS • Adaptive Enterprise Architecture • Final Year Capstone Edition
      </div>
    </div>
  );
};

src/components/requests/ProcurementReque:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  ProcurementRequest,
  RequestItem,
  RequestPriority,
  RequestStatus,
} from '../../types';
import {
  Plus,
  Search,
  Filter,
  FileText,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
  ArrowRight,
  ExternalLink,
  ChevronRight,
  Sparkles,
  Paperclip,
  Trash2,
  Calendar,
  Building,
  User,
  DollarSign,
  Tag,
  Shield,
  Layers,
} from 'lucide-react';

export const ProcurementRequestsView: React.FC<{
  isOpenCreateModal: boolean;
  setIsOpenCreateModal: (open: boolean) => void;
}> = ({ isOpenCreateModal, setIsOpenCreateModal }) => {
  const {
    requests,
    createRequest,
    currentUser,
    departments,
    locations,
    formatCurrency,
    t,
    orgConfig,
    approveRequest,
    rejectRequest,
    createRFQ,
    createPurchaseOrder,
    vendors,
  } = useApp();

  const [selectedReq, setSelectedReq] = useState<ProcurementRequest | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Form states for New Request Modal
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [departmentId, setDepartmentId] = useState(departments[0]?.id || '');
  const [locationId, setLocationId] = useState(locations[0]?.id || '');
  const [category, setCategory] = useState('IT Equipment');
  const [priority, setPriority] = useState<RequestPriority>('medium');
  const [requiredDate, setRequiredDate] = useState('');
  const [fundingSource, setFundingSource] = useState('Capital Expenditure (CapEx)');
  const [justification, setJustification] = useState('');
  const [technicalSpecs, setTechnicalSpecs] = useState('');
  const [isRecurring, setIsRecurring] = useState(false);
  const [items, setItems] = useState<RequestItem[]>([
    {
      id: 'item_1',
      description: '',
      category: 'General',
      quantity: 1,
      unit: 'units',
      estimatedUnitPrice: 0,
      totalPrice: 0,
    },
  ]);

  const addItemRow = () => {
    setItems((prev) => [
      ...prev,
      {
        id: `item_${Date.now()}`,
        description: '',
        category: 'General',
        quantity: 1,
        unit: 'units',
        estimatedUnitPrice: 0,
        totalPrice: 0,
      },
    ]);
  };

  const updateItemRow = (id: string, updates: Partial<RequestItem>) => {
    setItems((prev) =>
      prev.map((item) => {
        if (item.id !== id) return item;
        const updated = { ...item, ...updates };
        updated.totalPrice = updated.quantity * updated.estimatedUnitPrice;
        return updated;
      })
    );
  };

  const removeItemRow = (id: string) => {
    if (items.length <= 1) return;
    setItems((prev) => prev.filter((i) => i.id !== id));
  };

  const totalCalculatedBudget = items.reduce((acc, it) => acc + it.totalPrice, 0);

  const handleSubmitRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    const matchedDept = departments.find((d) => d.id === departmentId);
    const matchedLoc = locations.find((l) => l.id === locationId);

    createRequest({
      title,
      description,
      requesterId: currentUser.id,
      requesterName: currentUser.name,
      departmentId: orgConfig.hasDepartments ? departmentId : undefined,
      departmentName: orgConfig.hasDepartments ? matchedDept?.name : undefined,
      locationId: orgConfig.hasMultipleLocations ? locationId : undefined,
      locationName: orgConfig.hasMultipleLocations ? matchedLoc?.name : undefined,
      category,
      priority,
      requiredDate: requiredDate || new Date(Date.now() + 14 * 86400000).toISOString().split('T')[0],
      estimatedBudget: totalCalculatedBudget || 1000,
      fundingSource,
      justification,
      technicalSpecs,
      status: orgConfig.approvalWorkflow === 'none' ? 'approved' : 'pending_approval',
      items: items.filter((i) => i.description.trim().length > 0),
      isRecurring,
    });

    // Reset & close
    setTitle('');
    setDescription('');
    setJustification('');
    setTechnicalSpecs('');
    setIsOpenCreateModal(false);
  };

  // Filter requests
  const filteredRequests = requests.filter((r) => {
    const matchesStatus = statusFilter === 'all' || r.status === statusFilter;
    const matchesSearch =
      r.requestNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
      r.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      r.requesterName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (r.departmentName && r.departmentName.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesStatus && matchesSearch;
  });

  return (
    <div className="space-y-6">
      {/* View Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">Procurement Requests</h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Create, audit, and track purchase requisitions across all departments and project locations.
          </p>
        </div>
        <button
          onClick={() => setIsOpenCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-md shadow-indigo-500/20 transition self-start sm:self-auto"
        >
          <Plus className="w-4 h-4" />
          <span>New Purchase Request</span>
        </button>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3 bg-slate-900/60 p-3 rounded-2xl border border-slate-800">
        <div className="relative w-full sm:w-80">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by title, number, requester..."
            className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-9 pr-4 py-2 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto text-xs">
          {[
            { key: 'all', label: 'All Requests' },
            { key: 'pending_approval', label: 'Pending Approval' },
            { key: 'approved', label: 'Approved' },
            { key: 'converted_to_rfq', label: 'In Tender / RFQ' },
            { key: 'rejected', label: 'Rejected' },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => setStatusFilter(tab.key)}
              className={`px-3 py-1.5 rounded-xl font-medium transition flex-shrink-0 ${
                statusFilter === tab.key
                  ? 'bg-indigo-600 text-white'
                  : 'bg-slate-950 text-slate-400 hover:text-slate-200 border border-slate-800'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Requests Grid / Table */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-3">
          {filteredRequests.length === 0 ? (
            <div className="p-12 text-center rounded-2xl border border-slate-800 bg-slate-900/40 text-slate-400 text-xs">
              No procurement requests found matching your filter criteria.
            </div>
          ) : (
            filteredRequests.map((r) => {
              const isSelected = selectedReq?.id === r.id;
              return (
                <div
                  key={r.id}
                  onClick={() => setSelectedReq(r)}
                  className={`p-4 sm:p-5 rounded-2xl border cursor-pointer transition text-left ${
                    isSelected
                      ? 'border-indigo-500 bg-slate-900 shadow-lg shadow-indigo-500/10'
                      : 'border-slate-800 bg-slate-900/60 hover:bg-slate-900 hover:border-slate-700'
                  }`}
                >
                  <div className="flex items-start justify-between gap-3 mb-2">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-xs font-bold text-white">{r.requestNumber}</span>
                        <span
                          className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                            r.status === 'approved'
                              ? 'bg-emerald-500/20 text-emerald-400'
                              : r.status === 'pending_approval'
                              ? 'bg-amber-500/20 text-amber-400'
                              : r.status === 'rejected'
                              ? 'bg-rose-500/20 text-rose-400'
                              : 'bg-sky-500/20 text-sky-400'
                          }`}
                        >
                          {r.status.replace('_', ' ').toUpperCase()}
                        </span>
                        <span
                          className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${
                            r.priority === 'urgent'
                              ? 'bg-rose-500/20 text-rose-300'
                              : r.priority === 'high'
                              ? 'bg-amber-500/20 text-amber-300'
                              : 'bg-slate-800 text-slate-300'
                          }`}
                        >
                          {r.priority.toUpperCase()}
                        </span>
                      </div>
                      <h3 className="text-sm font-bold text-white mt-1">{r.title}</h3>
                    </div>

                    <div className="text-right">
                      <div className="text-sm font-black text-white">{formatCurrency(r.estimatedBudget)}</div>
                      <span className="text-[10px] text-slate-500">Est. Budget</span>
                    </div>
                  </div>

                  <p className="text-xs text-slate-400 line-clamp-2 leading-relaxed mb-3">
                    {r.description}
                  </p>

                  <div className="flex flex-wrap items-center justify-between text-[11px] text-slate-500 pt-3 border-t border-slate-800/80">
                    <div className="flex items-center gap-3">
                      <span>Requester: <strong>{r.requesterName}</strong></span>
                      {r.departmentName && <span>• {r.departmentName}</span>}
                    </div>
                    <div>Required by: {r.requiredDate}</div>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Selected Request Detail Sidebar Drawer */}
        <div className="lg:col-span-1">
          {selectedReq ? (
            <div className="sticky top-20 rounded-2xl border border-slate-800 bg-slate-900 p-5 space-y-4 shadow-xl">
              <div className="flex items-center justify-between pb-3 border-b border-slate-800">
                <div>
                  <span className="font-mono text-xs font-bold text-indigo-400">{selectedReq.requestNumber}</span>
                  <h3 className="text-sm font-bold text-white mt-0.5">{selectedReq.title}</h3>
                </div>
                <span
                  className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    selectedReq.status === 'approved'
                      ? 'bg-emerald-500/20 text-emerald-400'
                      : 'bg-amber-500/20 text-amber-400'
                  }`}
                >
                  {selectedReq.status.replace('_', ' ').toUpperCase()}
                </span>
              </div>

              {/* Justification & Specs */}
              <div>
                <span className="text-[11px] font-semibold text-slate-400 block mb-1">Business Justification</span>
                <p className="text-xs text-slate-300 leading-relaxed bg-slate-950 p-3 rounded-xl border border-slate-800">
                  {selectedReq.justification || 'Standard departmental purchase according to annual procurement calendar.'}
                </p>
              </div>

              {selectedReq.technicalSpecs && (
                <div>
                  <span className="text-[11px] font-semibold text-slate-400 block mb-1">Technical Specifications</span>
                  <p className="text-xs text-slate-300 leading-relaxed bg-slate-950 p-3 rounded-xl border border-slate-800 font-mono text-[11px]">
                    {selectedReq.technicalSpecs}
                  </p>
                </div>
              )}

              {/* Line Items */}
              <div>
                <span className="text-[11px] font-semibold text-slate-400 block mb-1.5">
                  Line Items ({selectedReq.items.length})
                </span>
                <div className="space-y-1.5">
                  {selectedReq.items.map((it) => (
                    <div
                      key={it.id}
                      className="p-2.5 rounded-xl bg-slate-950/60 border border-slate-800 text-xs flex justify-between items-center"
                    >
                      <div>
                        <div className="font-semibold text-white">{it.description}</div>
                        <div className="text-[10px] text-slate-500">
                          {it.quantity} {it.unit} @ {formatCurrency(it.estimatedUnitPrice)}
                        </div>
                      </div>
                      <div className="font-bold text-white">{formatCurrency(it.totalPrice)}</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Approval History */}
              <div>
                <span className="text-[11px] font-semibold text-slate-400 block mb-1.5">Approval Lifecycle</span>
                <div className="space-y-2">
                  {selectedReq.approvalsHistory.map((step, idx) => (
                    <div key={idx} className="p-2.5 rounded-xl bg-slate-950 border border-slate-800 text-xs">
                      <div className="flex items-center justify-between">
                        <span className="font-bold text-slate-200">{step.stepName}</span>
                        <span
                          className={`text-[10px] font-bold ${
                            step.status === 'approved' ? 'text-emerald-400' : 'text-amber-400'
                          }`}
                        >
                          {step.status.toUpperCase()}
                        </span>
                      </div>
                      <div className="text-[11px] text-slate-400 mt-0.5">By {step.approverName}</div>
                      {step.comments && (
                        <div className="text-[11px] text-slate-500 italic mt-1">"{step.comments}"</div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* Action Buttons */}
              <div className="pt-3 border-t border-slate-800 space-y-2">
                {selectedReq.status === 'pending_approval' && (
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      onClick={() => approveRequest(selectedReq.id)}
                      className="py-2 px-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs transition"
                    >
                      Authorize / Signoff
                    </button>
                    <button
                      onClick={() => rejectRequest(selectedReq.id, 'Budget cap exceeded')}
                      className="py-2 px-3 rounded-xl bg-rose-600/80 hover:bg-rose-500 text-white font-bold text-xs transition"
                    >
                      Reject
                    </button>
                  </div>
                )}

                {selectedReq.status === 'approved' && orgConfig.hasRfqs && (
                  <button
                    onClick={() => {
                      createRFQ({
                        title: `Tender for ${selectedReq.title}`,
                        procurementRequestId: selectedReq.id,
                        deliveryLocation: selectedReq.locationName || 'Main Headquarters',
                        closingDate: new Date(Date.now() + 10 * 86400000).toISOString().split('T')[0],
                        invitedVendorIds: vendors.slice(0, 2).map((v) => v.id),
                        criteriaWeights: { price: 40, quality: 25, delivery: 20, vendorHistory: 15 },
                        items: selectedReq.items.map((it, idx) => ({
                          id: `rfqi_${Date.now()}_${idx}`,
                          description: it.description,
                          quantity: it.quantity,
                          unit: it.unit,
                          specifications: selectedReq.technicalSpecs || 'Commercial standard quality',
                        })),
                      });
                    }}
                    className="w-full py-2.5 px-3 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs shadow-md transition flex items-center justify-center gap-1.5"
                  >
                    <Sparkles className="w-3.5 h-3.5" />
                    <span>Convert to RFQ / Tender</span>
                  </button>
                )}

                {selectedReq.status === 'approved' && (
                  <button
                    onClick={() => {
                      const vendor = vendors[0];
                      const subtotal = selectedReq.estimatedBudget;
                      const tax = (subtotal * orgConfig.taxRate) / 100;
                      createPurchaseOrder({
                        requestId: selectedReq.id,
                        vendorId: vendor.id,
                        vendorName: vendor.companyName,
                        vendorEmail: vendor.email,
                        items: selectedReq.items.map((it, idx) => ({
                          id: `poi_${Date.now()}_${idx}`,
                          description: it.description,
                          quantityOrdered: it.quantity,
                          quantityReceived: 0,
                          unitPrice: it.estimatedUnitPrice,
                          totalPrice: it.totalPrice,
                        })),
                        subtotal,
                        taxAmount: tax,
                        shippingAmount: 150,
                        totalAmount: subtotal + tax + 150,
                        deliveryTerms: 'DAP (Delivered at Place)',
                        paymentTerms: 'Net 30 Days',
                        expectedDeliveryDate: selectedReq.requiredDate,
                        deliveryAddress: selectedReq.locationName || 'HQ Logistics Dock',
                        notes: `Generated from ${selectedReq.requestNumber}`,
                      });
                    }}
                    className="w-full py-2 px-3 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-bold text-xs transition"
                  >
                    Issue Direct PO to Supplier
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div className="p-8 rounded-2xl border border-slate-800/80 bg-slate-900/30 text-center text-xs text-slate-500">
              Select a procurement request from the left to view detailed breakdown, specifications, line items, and approval steps.
            </div>
          )}
        </div>
      </div>

      {/* NEW REQUEST MODAL */}
      {isOpenCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 overflow-y-auto">
          <div className="relative w-full max-w-3xl rounded-3xl bg-slate-900 border border-slate-800 shadow-2xl p-6 sm:p-8 text-left my-8 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between pb-4 border-b border-slate-800 mb-6">
              <div>
                <h2 className="text-lg font-bold text-white">Create Procurement Requisition</h2>
                <p className="text-xs text-slate-400">
                  Submit items for budget verification and approval routing.
                </p>
              </div>
              <button
                onClick={() => setIsOpenCreateModal(false)}
                className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleSubmitRequest} className="space-y-5">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                  Request Title / Purpose *
                </label>
                <input
                  type="text"
                  required
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g. Ergonomic Chairs for Operations Wing"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {orgConfig.hasDepartments && (
                  <div>
                    <label className="block text-xs font-semibold text-slate-300 mb-1.5">Department</label>
                    <select
                      value={departmentId}
                      onChange={(e) => setDepartmentId(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-indigo-500"
                    >
                      {departments.map((d) => (
                        <option key={d.id} value={d.id}>
                          {d.name} ({d.code})
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                {orgConfig.hasMultipleLocations && (
                  <div>
                    <label className="block text-xs font-semibold text-slate-300 mb-1.5">Location / Site</label>
                    <select
                      value={locationId}
                      onChange={(e) => setLocationId(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-indigo-500"
                    >
                      {locations.map((l) => (
                        <option key={l.id} value={l.id}>
                          {l.name}
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Priority</label>
                  <select
                    value={priority}
                    onChange={(e) => setPriority(e.target.value as RequestPriority)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-indigo-500"
                  >
                    <option value="low">Low Priority</option>
                    <option value="medium">Medium Priority</option>
                    <option value="high">High Priority</option>
                    <option value="urgent">Urgent / Emergency</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">Description & Scope</label>
                <textarea
                  rows={2}
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Detailed context of the purchase requirement..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
                />
              </div>

              {/* Line Items Table */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-xs font-semibold text-slate-300">Itemized Line Items *</label>
                  <button
                    type="button"
                    onClick={addItemRow}
                    className="text-xs text-indigo-400 hover:text-indigo-300 font-bold flex items-center gap-1"
                  >
                    <Plus className="w-3 h-3" />
                    <span>Add Item</span>
                  </button>
                </div>

                <div className="space-y-2">
                  {items.map((item, idx) => (
                    <div
                      key={item.id}
                      className="grid grid-cols-12 gap-2 bg-slate-950 p-2.5 rounded-xl border border-slate-800 items-center"
                    >
                      <div className="col-span-5">
                        <input
                          type="text"
                          required
                          value={item.description}
                          onChange={(e) => updateItemRow(item.id, { description: e.target.value })}
                          placeholder="Item name / specification"
                          className="w-full bg-transparent text-xs text-white placeholder-slate-600 focus:outline-none"
                        />
                      </div>
                      <div className="col-span-2">
                        <input
                          type="number"
                          min="1"
                          value={item.quantity}
                          onChange={(e) => updateItemRow(item.id, { quantity: Number(e.target.value) })}
                          placeholder="Qty"
                          className="w-full bg-slate-900 border border-slate-800 rounded-lg px-2 py-1 text-xs text-white text-center focus:outline-none"
                        />
                      </div>
                      <div className="col-span-3">
                        <input
                          type="number"
                          min="0"
                          step="any"
                          value={item.estimatedUnitPrice || ''}
                          onChange={(e) => updateItemRow(item.id, { estimatedUnitPrice: Number(e.target.value) })}
                          placeholder="Unit Price"
                          className="w-full bg-slate-900 border border-slate-800 rounded-lg px-2 py-1 text-xs text-white focus:outline-none"
                        />
                      </div>
                      <div className="col-span-2 flex items-center justify-between">
                        <span className="text-xs font-bold text-slate-200">
                          {formatCurrency(item.totalPrice)}
                        </span>
                        {items.length > 1 && (
                          <button
                            type="button"
                            onClick={() => removeItemRow(item.id)}
                            className="p-1 text-slate-500 hover:text-rose-400"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>

                <div className="mt-2 flex justify-end text-xs font-bold text-white">
                  <span>Total Calculated Budget: {formatCurrency(totalCalculatedBudget)}</span>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Business Justification</label>
                  <textarea
                    rows={2}
                    value={justification}
                    onChange={(e) => setJustification(e.target.value)}
                    placeholder="Why is this purchase essential for operations?"
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Technical Specs / Standards</label>
                  <textarea
                    rows={2}
                    value={technicalSpecs}
                    onChange={(e) => setTechnicalSpecs(e.target.value)}
                    placeholder="Certifications, wattage, model numbers, dimensions..."
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
                  />
                </div>
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-slate-800">
                <button
                  type="button"
                  onClick={() => setIsOpenCreateModal(false)}
                  className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs shadow-lg shadow-indigo-500/20 transition"
                >
                  Submit for Approval
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/approvals/ApprovalInboxVi:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  ApprovalRule,
  ProcurementRequest,
  UserRole,
} from '../../types';
import {
  CheckCircle,
  XCircle,
  Clock,
  ArrowRight,
  Shield,
  Layers,
  UserCheck,
  RotateCcw,
  Sliders,
  DollarSign,
  AlertTriangle,
  Building,
  Check,
} from 'lucide-react';

export const ApprovalInboxView: React.FC = () => {
  const {
    requests,
    approveRequest,
    rejectRequest,
    invoices,
    approveInvoice,
    currentUser,
    formatCurrency,
    orgConfig,
    departments,
  } = useApp();

  const [activeTab, setActiveTab] = useState<'inbox' | 'matrix'>('inbox');
  const [commentModal, setCommentModal] = useState<{
    id: string;
    type: 'request' | 'invoice';
    action: 'approve' | 'reject' | 'return';
    title: string;
  } | null>(null);
  const [actionComment, setActionComment] = useState('');

  // Sample matrix rules
  const [matrixRules, setMatrixRules] = useState<ApprovalRule[]>([
    {
      id: 'rule_1',
      tierName: 'Tier 1 - Standard Purchasing',
      minAmount: 0,
      maxAmount: 5000,
      requiredRole: 'approver',
      autoEscalateDays: 3,
    },
    {
      id: 'rule_2',
      tierName: 'Tier 2 - Departmental Management',
      minAmount: 5001,
      maxAmount: 25000,
      requiredRole: 'procurement_officer',
      autoEscalateDays: 2,
    },
    {
      id: 'rule_3',
      tierName: 'Tier 3 - Executive Board Signoff',
      minAmount: 25001,
      maxAmount: Infinity,
      requiredRole: 'owner',
      autoEscalateDays: 1,
    },
  ]);

  const pendingRequests = requests.filter((r) => r.status === 'pending_approval');
  const pendingInvoices = invoices.filter((i) => i.status === 'exception' || i.status === 'pending_review');

  const handleConfirmAction = () => {
    if (!commentModal) return;

    if (commentModal.type === 'request') {
      if (commentModal.action === 'approve') {
        approveRequest(commentModal.id, actionComment);
      } else if (commentModal.action === 'reject') {
        rejectRequest(commentModal.id, actionComment || 'Rejected by policy');
      } else {
        rejectRequest(commentModal.id, actionComment ? `Returned for revision: ${actionComment}` : 'Returned for revision');
      }
    } else if (commentModal.type === 'invoice') {
      approveInvoice(commentModal.id);
    }

    setCommentModal(null);
    setActionComment('');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">Approval Center</h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Review requisitions, inspect budget commitments, and enforce organizational authorization thresholds.
          </p>
        </div>

        <div className="flex items-center gap-2 bg-slate-900 p-1 rounded-xl border border-slate-800 text-xs">
          <button
            onClick={() => setActiveTab('inbox')}
            className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
              activeTab === 'inbox' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            <Clock className="w-3.5 h-3.5" />
            <span>Approval Queue ({pendingRequests.length + pendingInvoices.length})</span>
          </button>
          <button
            onClick={() => setActiveTab('matrix')}
            className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
              activeTab === 'matrix' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            <Sliders className="w-3.5 h-3.5" />
            <span>Approval Matrix Rules</span>
          </button>
        </div>
      </div>

      {activeTab === 'inbox' ? (
        <div className="space-y-6">
          {/* Pending Requests */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2">
                <CheckCircle className="w-4 h-4 text-emerald-400" />
                <span>Requisition Approvals ({pendingRequests.length})</span>
              </h2>
            </div>

            {pendingRequests.length === 0 ? (
              <div className="p-8 text-center rounded-2xl border border-slate-800 bg-slate-900/40 text-slate-400 text-xs">
                No procurement requests are currently waiting in your approval inbox.
              </div>
            ) : (
              <div className="space-y-3">
                {pendingRequests.map((req) => (
                  <div
                    key={req.id}
                    className="p-5 rounded-2xl border border-slate-800 bg-slate-900/90 shadow-md flex flex-col lg:flex-row lg:items-center justify-between gap-4"
                  >
                    <div className="space-y-1.5 max-w-2xl">
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-xs font-bold text-indigo-400">{req.requestNumber}</span>
                        <span
                          className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                            req.priority === 'urgent'
                              ? 'bg-rose-500/20 text-rose-300'
                              : 'bg-amber-500/20 text-amber-300'
                          }`}
                        >
                          {req.priority.toUpperCase()}
                        </span>
                        {req.departmentName && (
                          <span className="text-[11px] text-slate-400">• {req.departmentName}</span>
                        )}
                      </div>
                      <h3 className="text-sm font-bold text-white">{req.title}</h3>
                      <p className="text-xs text-slate-400 leading-relaxed">{req.description}</p>
                      <div className="text-[11px] text-slate-500">
                        Submitted by <strong>{req.requesterName}</strong> • Needed by: {req.requiredDate} • Budget Code:{' '}
                        {req.budgetCode || 'Standard Cost Center'}
                      </div>
                    </div>

                    <div className="flex flex-col sm:flex-row items-end sm:items-center gap-4 border-t lg:border-t-0 pt-3 lg:pt-0 border-slate-800">
                      <div className="text-right">
                        <div className="text-base font-black text-white">{formatCurrency(req.estimatedBudget)}</div>
                        <span className="text-[10px] text-slate-400 block">Total Requisition</span>
                      </div>

                      <div className="flex items-center gap-2">
                        <button
                          onClick={() =>
                            setCommentModal({
                              id: req.id,
                              type: 'request',
                              action: 'approve',
                              title: `Authorize ${req.requestNumber} (${formatCurrency(req.estimatedBudget)})`,
                            })
                          }
                          className="px-3 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs transition flex items-center gap-1.5 shadow-sm"
                        >
                          <Check className="w-3.5 h-3.5" />
                          <span>Approve</span>
                        </button>
                        <button
                          onClick={() =>
                            setCommentModal({
                              id: req.id,
                              type: 'request',
                              action: 'return',
                              title: `Return ${req.requestNumber} for revision`,
                            })
                          }
                          className="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-semibold text-xs transition"
                        >
                          Revise
                        </button>
                        <button
                          onClick={() =>
                            setCommentModal({
                              id: req.id,
                              type: 'request',
                              action: 'reject',
                              title: `Reject Requisition ${req.requestNumber}`,
                            })
                          }
                          className="px-3 py-2 rounded-xl bg-rose-600/80 hover:bg-rose-500 text-white font-bold text-xs transition"
                        >
                          Reject
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Pending Invoices / Discrepancy Clearances */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2">
                <AlertTriangle className="w-4 h-4 text-purple-400" />
                <span>Invoice Exceptions Requiring Signoff ({pendingInvoices.length})</span>
              </h2>
            </div>

            <div className="space-y-3">
              {pendingInvoices.map((inv) => (
                <div
                  key={inv.id}
                  className="p-5 rounded-2xl border border-purple-500/20 bg-slate-900/90 shadow-md flex flex-col lg:flex-row lg:items-center justify-between gap-4"
                >
                  <div className="space-y-1 max-w-2xl">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-xs font-bold text-purple-400">{inv.invoiceNumber}</span>
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-500/20 text-purple-300">
                        {inv.status.toUpperCase()}
                      </span>
                      <span className="text-[11px] text-slate-400">• Vendor: {inv.vendorName}</span>
                    </div>
                    <div className="text-xs text-rose-300 font-medium">
                      {inv.threeWayMatch.discrepancyNote || 'Pending finance verification'}
                    </div>
                    <div className="text-[11px] text-slate-500">Linked to PO: {inv.poNumber} • Due Date: {inv.dueDate}</div>
                  </div>

                  <div className="flex items-center gap-4">
                    <div className="text-right">
                      <div className="text-base font-black text-white">{formatCurrency(inv.totalAmount)}</div>
                      <span className="text-[10px] text-slate-400">Total Billed</span>
                    </div>
                    <button
                      onClick={() =>
                        setCommentModal({
                          id: inv.id,
                          type: 'invoice',
                          action: 'approve',
                          title: `Override & Authorize Invoice ${inv.invoiceNumber}`,
                        })
                      }
                      className="px-3.5 py-2 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-bold text-xs transition"
                    >
                      Authorize Clearance
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : (
        /* Approval Matrix Configuration Table */
        <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6 space-y-6">
          <div>
            <h2 className="text-base font-bold text-white">Spend Authorization Matrix</h2>
            <p className="text-xs text-slate-400 mt-0.5">
              Specify which organizational roles are mandated to approve requisitions within each monetary tier.
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-800 text-slate-400 font-semibold uppercase text-[10px]">
                  <th className="pb-3">Threshold Tier Name</th>
                  <th className="pb-3">Minimum Value</th>
                  <th className="pb-3">Maximum Value</th>
                  <th className="pb-3">Mandatory Signoff Role</th>
                  <th className="pb-3">Auto-Escalation</th>
                  <th className="pb-3 text-right">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {matrixRules.map((rule) => (
                  <tr key={rule.id} className="text-slate-300">
                    <td className="py-3.5 font-bold text-white">{rule.tierName}</td>
                    <td className="py-3.5 font-mono">{formatCurrency(rule.minAmount)}</td>
                    <td className="py-3.5 font-mono">
                      {rule.maxAmount === Infinity ? 'Unlimited / Max' : formatCurrency(rule.maxAmount)}
                    </td>
                    <td className="py-3.5">
                      <span className="px-2.5 py-1 rounded-lg bg-indigo-500/10 text-indigo-400 font-bold border border-indigo-500/20 capitalize">
                        {rule.requiredRole.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="py-3.5 text-slate-400">{rule.autoEscalateDays} Business Days</td>
                    <td className="py-3.5 text-right text-emerald-400 font-bold">Active Rule</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 text-xs text-slate-400 flex items-start gap-3">
            <Shield className="w-5 h-5 text-indigo-400 flex-shrink-0 mt-0.5" />
            <div>
              <strong className="text-white">Enterprise Governance Protocol:</strong> Purchases exceeding the tier threshold automatically trigger secondary signoff. If an approver is out of office, delegation rules automatically route tasks to their appointed deputy.
            </div>
          </div>
        </div>
      )}

      {/* Action / Comment Modal */}
      {commentModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 backdrop-blur-sm p-4">
          <div className="w-full max-w-md rounded-2xl bg-slate-900 border border-slate-800 p-6 shadow-2xl text-left">
            <h3 className="text-sm font-bold text-white">{commentModal.title}</h3>
            <p className="text-xs text-slate-400 mt-1">
              Add any optional authorization comments, inspection notes, or instructions for the audit trail.
            </p>

            <textarea
              rows={3}
              value={actionComment}
              onChange={(e) => setActionComment(e.target.value)}
              placeholder="e.g. Approved within Q4 infrastructure cap; expediting delivery..."
              className="mt-4 w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-xs text-white placeholder-slate-600 focus:outline-none focus:border-indigo-500"
            />

            <div className="mt-5 flex items-center justify-end gap-2">
              <button
                onClick={() => setCommentModal(null)}
                className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmAction}
                className={`px-4 py-2 rounded-xl text-white font-bold text-xs shadow-md transition ${
                  commentModal.action === 'approve'
                    ? 'bg-emerald-600 hover:bg-emerald-500'
                    : commentModal.action === 'reject'
                    ? 'bg-rose-600 hover:bg-rose-500'
                    : 'bg-amber-600 hover:bg-amber-500'
                }`}
              >
                Confirm Action
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

