import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  Bid,
  RFQ,
  RFQItem,
} from '../../types';
import {
  Plus,
  FileSpreadsheet,
  Award,
  Users,
  CheckCircle,
  Clock,
  Sparkles,
  TrendingUp,
  ShieldCheck,
  ChevronRight,
  ArrowRight,
  ExternalLink,
  Sliders,
  DollarSign,
  Calendar,
  Layers,
} from 'lucide-react';

export const RFQWorkspaceView: React.FC = () => {
  const {
    rfqs,
    bids,
    awardBid,
    submitBid,
    vendors,
    formatCurrency,
    t,
    orgConfig,
  } = useApp();

  const [selectedRfqId, setSelectedRfqId] = useState<string>(rfqs[0]?.id || '');
  const [activeTab, setActiveTab] = useState<'evaluation' | 'vendor_portal'>('evaluation');

  // Supplier portal submission simulation
  const [vendorBidAmount, setVendorBidAmount] = useState<number>(16500);
  const [vendorDeliveryDays, setVendorDeliveryDays] = useState<number>(10);
  const [vendorWarranty, setVendorWarranty] = useState<string>('3 Years Full Replacement');
  const [vendorNotes, setVendorNotes] = useState<string>('Ex-stock delivery with free setup.');
  const [vendorSubmitted, setVendorSubmitted] = useState<boolean>(false);

  const activeRfq = rfqs.find((r) => r.id === selectedRfqId) || rfqs[0];
  const rfqBids = bids.filter((b) => b.rfqId === activeRfq?.id);

  const handleSimulateVendorBid = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeRfq) return;

    submitBid(activeRfq.id, {
      rfqId: activeRfq.id,
      vendorId: vendors[3]?.id || 'v_4',
      vendorName: vendors[3]?.companyName || 'PrimeTech Solutions',
      totalAmount: vendorBidAmount,
      deliveryDays: vendorDeliveryDays,
      warrantyPeriod: vendorWarranty,
      validityDays: 60,
      complianceChecked: true,
      technicalScore: 94,
      financialScore: 90,
      totalWeightedScore: 92.4,
      items: activeRfq.items.map((item) => ({
        rfqItemId: item.id,
        unitPrice: Math.round(vendorBidAmount / item.quantity),
        totalPrice: vendorBidAmount,
        notes: 'Compliant with enterprise specification',
      })),
      comments: vendorNotes,
    });

    setVendorSubmitted(true);
    setTimeout(() => {
      setVendorSubmitted(false);
      setActiveTab('evaluation');
    }, 1200);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">
            Competitive Tender & RFQ Workspace
          </h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Issue transparent requests for quotation, evaluate bids against weighted criteria, and award contracts.
          </p>
        </div>

        <div className="flex items-center gap-2 bg-slate-900 p-1 rounded-xl border border-slate-800 text-xs">
          <button
            onClick={() => setActiveTab('evaluation')}
            className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
              activeTab === 'evaluation' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            <Sliders className="w-3.5 h-3.5" />
            <span>Bid Evaluation & Matrix</span>
          </button>

          <button
            onClick={() => setActiveTab('vendor_portal')}
            className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
              activeTab === 'vendor_portal' ? 'bg-sky-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            <Users className="w-3.5 h-3.5" />
            <span>Vendor Portal Simulator</span>
          </button>
        </div>
      </div>

      {/* RFQ Selection Bar */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {rfqs.map((rfq) => {
          const isSelected = rfq.id === activeRfq?.id;
          const count = bids.filter((b) => b.rfqId === rfq.id).length;
          return (
            <div
              key={rfq.id}
              onClick={() => setSelectedRfqId(rfq.id)}
              className={`p-4 rounded-2xl border cursor-pointer transition text-left ${
                isSelected
                  ? 'border-indigo-500 bg-slate-900 shadow-lg shadow-indigo-500/10'
                  : 'border-slate-800 bg-slate-900/60 hover:bg-slate-900'
              }`}
            >
              <div className="flex items-center justify-between text-xs mb-1">
                <span className="font-mono font-bold text-indigo-400">{rfq.rfqNumber}</span>
                <span
                  className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    rfq.status === 'awarded'
                      ? 'bg-emerald-500/20 text-emerald-400'
                      : 'bg-amber-500/20 text-amber-400'
                  }`}
                >
                  {rfq.status.toUpperCase()}
                </span>
              </div>
              <h3 className="text-xs font-bold text-white line-clamp-1">{rfq.title}</h3>
              <div className="flex items-center justify-between text-[11px] text-slate-500 mt-2">
                <span>{count} Proposals Received</span>
                <span>Closes: {rfq.closingDate.split('T')[0]}</span>
              </div>
            </div>
          );
        })}
      </div>

      {activeTab === 'evaluation' ? (
        activeRfq ? (
          <div className="space-y-6">
            {/* Active RFQ Specification Overview */}
            <div className="p-5 rounded-2xl bg-slate-900 border border-slate-800">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-slate-800">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-mono text-xs font-bold text-indigo-400">{activeRfq.rfqNumber}</span>
                    <h2 className="text-sm font-bold text-white">{activeRfq.title}</h2>
                  </div>
                  <p className="text-xs text-slate-400 mt-1">Delivery Destination: {activeRfq.deliveryLocation}</p>
                </div>

                {/* Criteria Weights */}
                <div className="flex items-center gap-2 text-[11px] text-slate-300">
                  <span className="text-slate-500">Evaluation Weights:</span>
                  <span className="px-2 py-0.5 rounded-md bg-slate-950 border border-slate-800">
                    Price: {activeRfq.criteriaWeights.price}%
                  </span>
                  <span className="px-2 py-0.5 rounded-md bg-slate-950 border border-slate-800">
                    Quality: {activeRfq.criteriaWeights.quality}%
                  </span>
                  <span className="px-2 py-0.5 rounded-md bg-slate-950 border border-slate-800">
                    Delivery: {activeRfq.criteriaWeights.delivery}%
                  </span>
                </div>
              </div>

              {/* Items required */}
              <div className="mt-4">
                <span className="text-xs font-semibold text-slate-400 block mb-2">Required Bill of Quantities</span>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {activeRfq.items.map((item) => (
                    <div key={item.id} className="p-3 rounded-xl bg-slate-950 border border-slate-800/80 text-xs">
                      <div className="font-bold text-white">
                        {item.quantity} {item.unit} — {item.description}
                      </div>
                      <div className="text-[11px] text-slate-400 mt-1 font-mono">{item.specifications}</div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* SIDE-BY-SIDE BID COMPARISON MATRIX (Mandatory per specification) */}
            <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6 space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-sm font-bold text-white flex items-center gap-2">
                    <Award className="w-4 h-4 text-amber-400" />
                    <span>Side-by-Side Competitive Bid Comparison Matrix</span>
                  </h3>
                  <p className="text-xs text-slate-400 mt-0.5">
                    Scores calculated dynamically based on criteria weightings and vendor track record.
                  </p>
                </div>
              </div>

              {rfqBids.length === 0 ? (
                <div className="p-12 text-center text-xs text-slate-400">
                  No bids have been submitted yet for this RFQ. Switch to the "Vendor Portal Simulator" to submit a bid as a supplier!
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead>
                      <tr className="border-b border-slate-800 text-slate-400 font-semibold uppercase text-[10px]">
                        <th className="pb-3">Vendor / Tenderer</th>
                        <th className="pb-3">Bid Amount</th>
                        <th className="pb-3">Lead Time</th>
                        <th className="pb-3">Warranty</th>
                        <th className="pb-3">Compliance</th>
                        <th className="pb-3">Weighted Score</th>
                        <th className="pb-3 text-right">Award Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/80">
                      {rfqBids.map((bid) => {
                        const isAwarded = bid.status === 'awarded';
                        return (
                          <tr key={bid.id} className="text-slate-300">
                            <td className="py-4">
                              <div className="font-bold text-white">{bid.vendorName}</div>
                              <div className="text-[11px] text-slate-500 italic">"{bid.comments}"</div>
                            </td>
                            <td className="py-4 font-mono font-bold text-white">
                              {formatCurrency(bid.totalAmount)}
                            </td>
                            <td className="py-4">{bid.deliveryDays} Days</td>
                            <td className="py-4 text-slate-400">{bid.warrantyPeriod}</td>
                            <td className="py-4">
                              <span className="px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 font-bold text-[10px] flex items-center gap-1 w-max">
                                <ShieldCheck className="w-3 h-3" /> Verified
                              </span>
                            </td>
                            <td className="py-4">
                              <div className="flex items-center gap-2">
                                <span className="text-sm font-black text-white">{bid.totalWeightedScore}</span>
                                <span className="text-[10px] text-slate-500">/ 100</span>
                              </div>
                            </td>
                            <td className="py-4 text-right">
                              {isAwarded ? (
                                <span className="px-3 py-1.5 rounded-xl bg-emerald-600/20 text-emerald-400 border border-emerald-500/30 text-xs font-bold inline-flex items-center gap-1.5">
                                  <CheckCircle className="w-3.5 h-3.5" /> Awarded & PO Issued
                                </span>
                              ) : (
                                <button
                                  onClick={() => awardBid(activeRfq.id, bid.id)}
                                  className="px-4 py-2 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-500 hover:from-emerald-500 hover:to-teal-400 text-white font-bold text-xs shadow-md transition"
                                >
                                  Award & Issue PO
                                </button>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        ) : null
      ) : (
        /* VENDOR PORTAL SIMULATOR (Mandatory per specification) */
        <div className="rounded-2xl border border-sky-500/30 bg-slate-900 p-6 sm:p-8 space-y-6">
          <div className="flex items-center justify-between pb-4 border-b border-slate-800">
            <div className="flex items-center gap-3">
              <div className="p-2.5 rounded-xl bg-sky-500/20 text-sky-400">
                <Users className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-base font-bold text-white">Vendor Portal: Bid Submission Experience</h2>
                <p className="text-xs text-slate-400">
                  Simulate how an invited supplier discovers opportunities, quotes unit rates, and submits tenders.
                </p>
              </div>
            </div>
            <span className="px-2.5 py-1 rounded-full bg-sky-500/20 text-sky-300 font-bold text-xs">
              Supplier View
            </span>
          </div>

          <form onSubmit={handleSimulateVendorBid} className="space-y-4 max-w-xl">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                Total Quotation Value ({orgConfig.currency})
              </label>
              <input
                type="number"
                required
                value={vendorBidAmount}
                onChange={(e) => setVendorBidAmount(Number(e.target.value))}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-sky-500"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                  Guaranteed Delivery Lead Time (Days)
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={vendorDeliveryDays}
                  onChange={(e) => setVendorDeliveryDays(Number(e.target.value))}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-sky-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                  Warranty & SLA Guarantee
                </label>
                <input
                  type="text"
                  required
                  value={vendorWarranty}
                  onChange={(e) => setVendorWarranty(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-sky-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                Technical Commentary & Commercial Terms
              </label>
              <textarea
                rows={2}
                value={vendorNotes}
                onChange={(e) => setVendorNotes(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2 text-xs text-white focus:outline-none focus:border-sky-500"
              />
            </div>

            <button
              type="submit"
              className="px-6 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-xs shadow-lg shadow-sky-500/20 transition"
            >
              {vendorSubmitted ? 'Bid Submitted Successfully!' : 'Submit Sealed Tender Proposal'}
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

src/components/deliveries/DeliveriesAndI:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  GoodsReceiptNote,
  InventoryItem,
  StockMovement,
} from '../../types';
import {
  Truck,
  Package,
  Plus,
  Search,
  CheckCircle,
  AlertTriangle,
  RotateCcw,
  Layers,
  ArrowRight,
  TrendingDown,
  Building,
  ShieldCheck,
  Calendar,
} from 'lucide-react';

export const DeliveriesAndInventoryView: React.FC<{
  isOpenNewGRN: boolean;
  setIsOpenNewGRN: (open: boolean) => void;
}> = ({ isOpenNewGRN, setIsOpenNewGRN }) => {
  const {
    goodsReceipts,
    inventoryItems,
    stockMovements,
    purchaseOrders,
    recordGoodsReceipt,
    adjustStock,
    currentUser,
    locations,
    formatCurrency,
    orgConfig,
    t,
  } = useApp();

  const [activeTab, setActiveTab] = useState<'deliveries' | 'inventory' | 'movements'>('deliveries');
  const [searchQuery, setSearchQuery] = useState('');

  // GRN Modal Form States
  const [selectedPOId, setSelectedPOId] = useState(purchaseOrders[0]?.id || '');
  const [deliveryNoteNumber, setDeliveryNoteNumber] = useState('DN-LOG-8891');
  const [locationId, setLocationId] = useState(locations[1]?.id || locations[0]?.id || '');
  const [comments, setComments] = useState('');
  const [receivedQtyInput, setReceivedQtyInput] = useState<number>(10);
  const [damagedQtyInput, setDamagedQtyInput] = useState<number>(0);
  const [missingQtyInput, setMissingQtyInput] = useState<number>(0);

  // Manual stock adjustment modal
  const [adjustModalItem, setAdjustModalItem] = useState<InventoryItem | null>(null);
  const [adjustQty, setAdjustQty] = useState<number>(0);
  const [adjustReason, setAdjustReason] = useState<string>('Cycle Count Reconciliation');

  const selectedPO = purchaseOrders.find((p) => p.id === selectedPOId) || purchaseOrders[0];

  const handleRecordGRN = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPO) return;

    const matchedLoc = locations.find((l) => l.id === locationId) || locations[0];

    const grnItems = selectedPO.items.map((it, idx) => ({
      poItemId: it.id,
      description: it.description,
      quantityOrdered: it.quantityOrdered,
      quantityReceived: receivedQtyInput,
      quantityDamaged: damagedQtyInput,
      quantityMissing: missingQtyInput,
      inspectionPassed: damagedQtyInput === 0 && missingQtyInput === 0,
    }));

    recordGoodsReceipt({
      purchaseOrderId: selectedPO.id,
      poNumber: selectedPO.poNumber,
      vendorName: selectedPO.vendorName,
      receiverUserId: currentUser.id,
      receiverName: currentUser.name,
      deliveryNoteNumber,
      locationId: matchedLoc.id,
      locationName: matchedLoc.name,
      items: grnItems,
      comments: comments || 'Standard dock delivery inspection conducted.',
    });

    setIsOpenNewGRN(false);
  };

  const handleApplyAdjustment = () => {
    if (!adjustModalItem) return;
    adjustStock(adjustModalItem.id, adjustQty, 'adjustment', adjustReason);
    setAdjustModalItem(null);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">
            Logistics, Goods Receipts & Inventory
          </h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Physical delivery verification, damage inspection, and automated warehouse inventory updates.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 bg-slate-900 p-1 rounded-xl border border-slate-800 text-xs">
            <button
              onClick={() => setActiveTab('deliveries')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'deliveries' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <Truck className="w-3.5 h-3.5" />
              <span>Deliveries & GRNs</span>
            </button>
            <button
              onClick={() => setActiveTab('inventory')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'inventory' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <Package className="w-3.5 h-3.5" />
              <span>Inventory Stock</span>
            </button>
            <button
              onClick={() => setActiveTab('movements')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'movements' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <Layers className="w-3.5 h-3.5" />
              <span>Movement Ledger</span>
            </button>
          </div>

          <button
            onClick={() => setIsOpenNewGRN(true)}
            className="flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-amber-600 hover:bg-amber-500 text-white text-xs font-bold shadow-md transition"
          >
            <Plus className="w-4 h-4" />
            <span>Record GRN</span>
          </button>
        </div>
      </div>

      {activeTab === 'deliveries' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 gap-3">
            {goodsReceipts.map((grn) => (
              <div
                key={grn.id}
                className="p-5 rounded-2xl border border-slate-800 bg-slate-900/90 shadow-md flex flex-col md:flex-row md:items-center justify-between gap-4"
              >
                <div className="space-y-1.5 max-w-2xl">
                  <div className="flex items-center gap-2">
                    <span className="font-mono text-xs font-bold text-amber-400">{grn.grnNumber}</span>
                    <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-800 text-slate-300">
                      PO: {grn.poNumber}
                    </span>
                    <span className="text-[11px] text-slate-400">• Vendor: {grn.vendorName}</span>
                  </div>

                  <div className="text-sm font-bold text-white">
                    Received at {grn.locationName} (Delivery Note #{grn.deliveryNoteNumber})
                  </div>

                  <div className="text-xs text-slate-300">
                    {grn.items.map((it) => (
                      <div key={it.poItemId} className="flex items-center gap-2 mt-0.5">
                        <span>• {it.description}:</span>
                        <strong className="text-white">{it.quantityReceived} accepted</strong>
                        {it.quantityDamaged > 0 && (
                          <span className="text-rose-400 font-bold">({it.quantityDamaged} Damaged)</span>
                        )}
                        {it.quantityMissing > 0 && (
                          <span className="text-amber-400 font-bold">({it.quantityMissing} Missing)</span>
                        )}
                      </div>
                    ))}
                  </div>

                  <div className="text-[11px] text-slate-500 italic mt-1">"{grn.comments}"</div>
                </div>

                <div className="text-right border-t md:border-t-0 pt-3 md:pt-0 border-slate-800">
                  <div className="text-xs text-slate-400">Inspected & Verified By</div>
                  <div className="text-sm font-bold text-white">{grn.receiverName}</div>
                  <div className="text-[11px] text-slate-500">{grn.receivedDate.split('T')[0]}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'inventory' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {inventoryItems.map((item) => {
              const isLowStock = item.currentStock <= item.minimumStock;
              return (
                <div
                  key={item.id}
                  className={`p-5 rounded-2xl border text-left flex flex-col justify-between transition ${
                    isLowStock
                      ? 'border-rose-500/40 bg-slate-900 shadow-lg shadow-rose-950/20'
                      : 'border-slate-800 bg-slate-900'
                  }`}
                >
                  <div>
                    <div className="flex items-center justify-between text-xs mb-2">
                      <span className="font-mono font-bold text-indigo-400">{item.sku}</span>
                      {isLowStock ? (
                        <span className="px-2 py-0.5 rounded-full bg-rose-500/20 text-rose-400 text-[10px] font-bold">
                          Low Stock Alert
                        </span>
                      ) : (
                        <span className="px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 text-[10px] font-bold">
                          Optimal Stock
                        </span>
                      )}
                    </div>

                    <h3 className="text-sm font-bold text-white mb-1 line-clamp-1">{item.name}</h3>
                    <p className="text-[11px] text-slate-400 mb-3">{item.locationName}</p>

                    <div className="flex items-baseline gap-2 mb-2">
                      <span className="text-2xl font-black text-white">{item.currentStock}</span>
                      <span className="text-xs text-slate-400">{item.unit} in stock</span>
                    </div>

                    <div className="w-full bg-slate-950 h-1.5 rounded-full overflow-hidden mb-3 border border-slate-800">
                      <div
                        className={`h-full rounded-full ${
                          isLowStock ? 'bg-rose-500' : 'bg-emerald-500'
                        }`}
                        style={{
                          width: `${Math.min(100, (item.currentStock / item.reorderLevel) * 100)}%`,
                        }}
                      />
                    </div>

                    <div className="flex items-center justify-between text-[11px] text-slate-500">
                      <span>Safety Min: {item.minimumStock}</span>
                      <span>Reorder At: {item.reorderLevel}</span>
                    </div>
                  </div>

                  <div className="mt-4 pt-3 border-t border-slate-800 flex items-center justify-between">
                    <span className="text-xs font-mono text-slate-300">
                      Avg: {formatCurrency(item.averageUnitCost)}
                    </span>
                    <button
                      onClick={() => setAdjustModalItem(item)}
                      className="px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-xs font-semibold text-slate-200 transition"
                    >
                      Adjust
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {activeTab === 'movements' && (
        <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6 space-y-4">
          <div>
            <h3 className="text-sm font-bold text-white">Stock Movement Audit Trail</h3>
            <p className="text-xs text-slate-400 mt-0.5">
              Automated log of receipts, inventory issues, and physical stock reconciliations.
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-800 text-slate-400 uppercase text-[10px]">
                  <th className="pb-3">Timestamp</th>
                  <th className="pb-3">Item Description</th>
                  <th className="pb-3">Action Type</th>
                  <th className="pb-3 text-center">Qty Variance</th>
                  <th className="pb-3 text-center">Resulting Stock</th>
                  <th className="pb-3">Reference</th>
                  <th className="pb-3 text-right">Logged By</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {stockMovements.map((mov) => (
                  <tr key={mov.id} className="text-slate-300">
                    <td className="py-3 font-mono text-slate-400">{mov.timestamp.split('T')[0]}</td>
                    <td className="py-3 font-bold text-white">{mov.itemName}</td>
                    <td className="py-3">
                      <span className="px-2 py-0.5 rounded-full bg-slate-800 text-[10px] font-bold text-slate-300 capitalize">
                        {mov.movementType.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="py-3 text-center font-bold text-emerald-400">
                      {mov.quantityChange > 0 ? `+${mov.quantityChange}` : mov.quantityChange}
                    </td>
                    <td className="py-3 text-center font-bold text-white">{mov.resultingStock}</td>
                    <td className="py-3 font-mono text-indigo-400">{mov.referenceId || 'MANUAL-ADJ'}</td>
                    <td className="py-3 text-right text-slate-400">{mov.performedBy}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* RECORD GRN MODAL */}
      {isOpenNewGRN && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 overflow-y-auto">
          <div className="relative w-full max-w-xl rounded-2xl bg-slate-900 border border-slate-800 shadow-2xl p-6 sm:p-8 text-left my-8">
            <h2 className="text-base font-bold text-white mb-1">Record Physical Goods Receipt Note (GRN)</h2>
            <p className="text-xs text-slate-400 mb-5">
              Receiving goods automatically syncs inventory stock in the selected warehouse.
            </p>

            <form onSubmit={handleRecordGRN} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">Purchase Order (PO)</label>
                <select
                  value={selectedPOId}
                  onChange={(e) => setSelectedPOId(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                >
                  {purchaseOrders.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.poNumber} — {p.vendorName} ({p.items.length} items)
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Supplier Delivery Note #</label>
                  <input
                    type="text"
                    required
                    value={deliveryNoteNumber}
                    onChange={(e) => setDeliveryNoteNumber(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-300 mb-1.5">Receiving Facility / Warehouse</label>
                  <select
                    value={locationId}
                    onChange={(e) => setLocationId(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                  >
                    {locations.map((l) => (
                      <option key={l.id} value={l.id}>
                        {l.name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="p-3.5 bg-slate-950 rounded-xl border border-slate-800 space-y-3">
                <span className="text-xs font-bold text-white block">Dock Inspection Counts</span>
                <div className="grid grid-cols-3 gap-2">
                  <div>
                    <label className="block text-[10px] text-slate-400 mb-1">Accepted Qty</label>
                    <input
                      type="number"
                      min="0"
                      value={receivedQtyInput}
                      onChange={(e) => setReceivedQtyInput(Number(e.target.value))}
                      className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-xs text-white text-center"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-rose-400 mb-1">Damaged Qty</label>
                    <input
                      type="number"
                      min="0"
                      value={damagedQtyInput}
                      onChange={(e) => setDamagedQtyInput(Number(e.target.value))}
                      className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-xs text-white text-center"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-amber-400 mb-1">Missing Qty</label>
                    <input
                      type="number"
                      min="0"
                      value={missingQtyInput}
                      onChange={(e) => setMissingQtyInput(Number(e.target.value))}
                      className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-xs text-white text-center"
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1.5">Inspection Remarks</label>
                <textarea
                  rows={2}
                  value={comments}
                  onChange={(e) => setComments(e.target.value)}
                  placeholder="Note damages, batch numbers, expiry dates, or freight notes..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-4 border-t border-slate-800">
                <button
                  type="button"
                  onClick={() => setIsOpenNewGRN(false)}
                  className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-2.5 rounded-xl bg-amber-600 hover:bg-amber-500 text-white font-bold text-xs shadow-md transition"
                >
                  Confirm & Sync Inventory
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ADJUST STOCK MODAL */}
      {adjustModalItem && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="w-full max-w-md rounded-2xl bg-slate-900 border border-slate-800 p-6 shadow-2xl text-left">
            <h3 className="text-sm font-bold text-white">Adjust Stock: {adjustModalItem.name}</h3>
            <p className="text-xs text-slate-400 mt-1">Current Stock: {adjustModalItem.currentStock} {adjustModalItem.unit}</p>

            <div className="mt-4 space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Adjustment Variance (+ or -)</label>
                <input
                  type="number"
                  value={adjustQty}
                  onChange={(e) => setAdjustQty(Number(e.target.value))}
                  placeholder="e.g. +5 or -2"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Reconciliation Reason</label>
                <input
                  type="text"
                  value={adjustReason}
                  onChange={(e) => setAdjustReason(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white"
                />
              </div>
            </div>

            <div className="mt-5 flex justify-end gap-2">
              <button
                onClick={() => setAdjustModalItem(null)}
                className="px-4 py-2 rounded-xl text-xs text-slate-400 hover:text-white"
              >
                Cancel
              </button>
              <button
                onClick={handleApplyAdjustment}
                className="px-4 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs"
              >
                Apply Adjustment
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/finance/FinanceAndThreeWa:
import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import {
  Invoice,
  PaymentRecord,
} from '../../types';
import {
  CreditCard,
  DollarSign,
  Plus,
  Search,
  CheckCircle,
  AlertTriangle,
  FileText,
  ShieldCheck,
  Send,
  Eye,
  Layers,
  ArrowRight,
  TrendingDown,
  Building,
} from 'lucide-react';

export const FinanceAndThreeWayMatchView: React.FC<{
  isOpenNewInvoice: boolean;
  setIsOpenNewInvoice: (open: boolean) => void;
}> = ({ isOpenNewInvoice, setIsOpenNewInvoice }) => {
  const {
    invoices,
    purchaseOrders,
    goodsReceipts,
    payments,
    budgets,
    createInvoice,
    approveInvoice,
    processPayment,
    formatCurrency,
    orgConfig,
    t,
  } = useApp();

  const [activeTab, setActiveTab] = useState<'invoices' | 'payments' | 'budgets'>('invoices');
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [payModalInvoice, setPayModalInvoice] = useState<Invoice | null>(null);
  const [payMethod, setPayMethod] = useState<'bank_transfer' | 'credit_card' | 'check'>('bank_transfer');
  const [txnRef, setTxnRef] = useState(`WIRE-${Date.now().toString().slice(-8)}`);

  // New Invoice Form
  const [selectedPOId, setSelectedPOId] = useState(purchaseOrders[0]?.id || '');
  const [vendorInvNum, setVendorInvNum] = useState('INV-VEN-7701');
  const [billedAmount, setBilledAmount] = useState<number>(3643.75);
  const [billedQty, setBilledQty] = useState<number>(20);

  const selectedPO = purchaseOrders.find((p) => p.id === selectedPOId) || purchaseOrders[0];

  const handleCreateInvoice = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPO) return;

    const subtotal = billedAmount;
    const taxAmount = (subtotal * orgConfig.taxRate) / 100;

    createInvoice({
      vendorInvoiceNumber: vendorInvNum,
      purchaseOrderId: selectedPO.id,
      poNumber: selectedPO.poNumber,
      vendorId: selectedPO.vendorId,
      vendorName: selectedPO.vendorName,
      subtotal,
      taxAmount,
      totalAmount: subtotal + taxAmount,
      issueDate: new Date().toISOString().split('T')[0],
      dueDate: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0],
      items: [
        {
          id: `inv_i_${Date.now()}`,
          description: selectedPO.items[0]?.description || 'Procured Material',
          quantityBilled: billedQty,
          unitPrice: selectedPO.items[0]?.unitPrice || 100,
          totalPrice: subtotal,
        },
      ],
    });

    setIsOpenNewInvoice(false);
  };

  const handleExecutePayment = () => {
    if (!payModalInvoice) return;

    processPayment({
      invoiceId: payModalInvoice.id,
      invoiceNumber: payModalInvoice.invoiceNumber,
      vendorId: payModalInvoice.vendorId,
      vendorName: payModalInvoice.vendorName,
      amount: payModalInvoice.totalAmount,
      paymentMethod: payMethod,
      transactionReference: txnRef,
    });

    setPayModalInvoice(null);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">
            Finance & Automated Three-Way Matching
          </h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Automated verification of Purchase Orders vs Goods Receipts vs Invoices before payment disbursement.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 bg-slate-900 p-1 rounded-xl border border-slate-800 text-xs">
            <button
              onClick={() => setActiveTab('invoices')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'invoices' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <FileText className="w-3.5 h-3.5" />
              <span>Invoices ({invoices.length})</span>
            </button>
            <button
              onClick={() => setActiveTab('payments')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'payments' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <CreditCard className="w-3.5 h-3.5" />
              <span>Disbursements ({payments.length})</span>
            </button>
            <button
              onClick={() => setActiveTab('budgets')}
              className={`px-3 py-1.5 rounded-lg font-bold transition flex items-center gap-1.5 ${
                activeTab === 'budgets' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
              }`}
            >
              <DollarSign className="w-3.5 h-3.5" />
              <span>Budgets & Cost Centers</span>
            </button>
          </div>

          <button
            onClick={() => setIsOpenNewInvoice(true)}
            className="flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white text-xs font-bold shadow-md transition"
          >
            <Plus className="w-4 h-4" />
            <span>Add Invoice</span>
          </button>
        </div>
      </div>

      {activeTab === 'invoices' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-3">
            {invoices.map((inv) => {
              const isMatched = inv.threeWayMatch.isMatched;
              const isSelected = selectedInvoice?.id === inv.id;
              return (
                <div
                  key={inv.id}
                  onClick={() => setSelectedInvoice(inv)}
                  className={`p-5 rounded-2xl border cursor-pointer transition text-left ${
                    isSelected
                      ? 'border-indigo-500 bg-slate-900 shadow-lg shadow-indigo-500/10'
                      : 'border-slate-800 bg-slate-900/80 hover:bg-slate-900'
                  }`}
                >
                  <div className="flex items-start justify-between gap-3 mb-2">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-xs font-bold text-white">{inv.invoiceNumber}</span>
                        {isMatched ? (
                          <span className="px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 text-[10px] font-bold flex items-center gap-1">
                            <ShieldCheck className="w-3 h-3" /> 3-Way Matched
                          </span>
                        ) : (
                          <span className="px-2 py-0.5 rounded-full bg-rose-500/20 text-rose-400 text-[10px] font-bold flex items-center gap-1">
                            <AlertTriangle className="w-3 h-3" /> Discrepancy Exception
                          </span>
                        )}
                        <span className="px-2 py-0.5 rounded-full bg-slate-800 text-slate-300 text-[10px] font-bold capitalize">
                          {inv.status}
                        </span>
                      </div>
                      <h3 className="text-sm font-bold text-white mt-1">{inv.vendorName}</h3>
                      <div className="text-[11px] text-slate-400">
                        Vendor Ref: {inv.vendorInvoiceNumber} • Linked PO: {inv.poNumber}
                      </div>
                    </div>

                    <div className="text-right">
                      <div className="text-base font-black text-white">{formatCurrency(inv.totalAmount)}</div>
                      <span className="text-[10px] text-slate-500">Due: {inv.dueDate}</span>
                    </div>
                  </div>

                  {!isMatched && (
                    <div className="mt-2 p-2.5 rounded-xl bg-rose-950/40 border border-rose-500/20 text-xs text-rose-300">
                      ⚠️ <strong>Match Warning:</strong> {inv.threeWayMatch.discrepancyNote}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* 3-WAY MATCH INSPECTION SIDEBAR DRAWER (Mandatory per specification) */}
          <div className="lg:col-span-1">
            {selectedInvoice ? (
              <div className="rounded-2xl border border-slate-800 bg-slate-900 p-5 space-y-4 shadow-xl">
                <div className="pb-3 border-b border-slate-800">
                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider block">
                    Three-Way Match Verification Engine
                  </span>
                  <h3 className="text-sm font-bold text-white mt-0.5">{selectedInvoice.invoiceNumber}</h3>
                  <div className="text-xs text-slate-400">{selectedInvoice.vendorName}</div>
                </div>

                {/* Side-by-side audit checks */}
                <div className="space-y-2.5 text-xs">
                  <div className="p-3 bg-slate-950 rounded-xl border border-slate-800 flex items-center justify-between">
                    <div>
                      <span className="font-semibold text-white block">1. PO Authorization Check</span>
                      <span className="text-[11px] text-slate-400">PO: {selectedInvoice.poNumber}</span>
                    </div>
                    <span className="text-emerald-400 font-bold">Passed</span>
                  </div>

                  <div className="p-3 bg-slate-950 rounded-xl border border-slate-800 flex items-center justify-between">
                    <div>
                      <span className="font-semibold text-white block">2. Goods Receipt (GRN) Audit</span>
                      <span className="text-[11px] text-slate-400">GRN: {selectedInvoice.grnNumber || 'Pending GRN'}</span>
                    </div>
                    <span
                      className={`font-bold ${
                        selectedInvoice.threeWayMatch.hasGrn ? 'text-emerald-400' : 'text-rose-400'
                      }`}
                    >
                      {selectedInvoice.threeWayMatch.hasGrn ? 'Verified' : 'Missing'}
                    </span>
                  </div>

                  <div className="p-3 bg-slate-950 rounded-xl border border-slate-800 flex items-center justify-between">
                    <div>
                      <span className="font-semibold text-white block">3. Quantity & Price Match</span>
                      <span className="text-[11px] text-slate-400">Tolerance: 0% variance</span>
                    </div>
                    <span
                      className={`font-bold ${
                        selectedInvoice.threeWayMatch.isMatched ? 'text-emerald-400' : 'text-rose-400'
                      }`}
                    >
                      {selectedInvoice.threeWayMatch.isMatched ? 'Passed' : 'Exception'}
                    </span>
                  </div>
                </div>

                {/* Actions */}
                <div className="pt-3 border-t border-slate-800 space-y-2">
                  {selectedInvoice.status !== 'paid' && (
                    <button
                      onClick={() => setPayModalInvoice(selectedInvoice)}
                      className="w-full py-2.5 px-4 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-500 hover:from-emerald-500 hover:to-teal-400 text-white font-bold text-xs shadow-md transition flex items-center justify-center gap-2"
                    >
                      <CreditCard className="w-4 h-4" />
                      <span>Authorize & Release Payment</span>
                    </button>
                  )}

                  {selectedInvoice.status === 'paid' && (
                    <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-xs text-center font-bold">
                      ✓ Invoice Settled & Cleared
                    </div>
                  )}

                  {!selectedInvoice.threeWayMatch.isMatched && selectedInvoice.status !== 'approved' && (
                    <button
                      onClick={() => approveInvoice(selectedInvoice.id)}
                      className="w-full py-2 px-3 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold transition"
                    >
                      Management Override (Approve Anyway)
                    </button>
                  )}
                </div>
              </div>
            ) : (
              <div className="p-8 rounded-2xl border border-slate-800/80 bg-slate-900/30 text-center text-xs text-slate-500">
                Select an invoice on the left to review the Three-Way Matching comparison between PO, GRN, and billed lines.
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6 space-y-4">
          <div>
            <h3 className="text-sm font-bold text-white">Disbursement Settlement Ledger</h3>
            <p className="text-xs text-slate-400 mt-0.5">
              Verified corporate payments cleared against Three-Way Matched invoices.
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-800 text-slate-400 uppercase text-[10px]">
                  <th className="pb-3">Disbursement #</th>
                  <th className="pb-3">Vendor</th>
                  <th className="pb-3">Invoice #</th>
                  <th className="pb-3">Payment Method</th>
                  <th className="pb-3">Transaction Reference</th>
                  <th className="pb-3">Date</th>
                  <th className="pb-3 text-right">Amount Cleared</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {payments.map((p) => (
                  <tr key={p.id} className="text-slate-300">
                    <td className="py-3.5 font-mono font-bold text-indigo-400">{p.paymentNumber}</td>
                    <td className="py-3.5 font-bold text-white">{p.vendorName}</td>
                    <td className="py-3.5 font-mono text-slate-400">{p.invoiceNumber}</td>
                    <td className="py-3.5 capitalize">{p.paymentMethod.replace('_', ' ')}</td>
                    <td className="py-3.5 font-mono text-[11px] text-slate-400">{p.transactionReference}</td>
                    <td className="py-3.5">{p.paymentDate}</td>
                    <td className="py-3.5 text-right font-black text-emerald-400 font-mono">
                      {formatCurrency(p.amount)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'budgets' && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {budgets.map((b) => {
            const spentPct = Math.round((b.spentAmount / b.allocatedAmount) * 100);
            const committedPct = Math.round((b.committedAmount / b.allocatedAmount) * 100);
            return (
              <div key={b.id} className="p-5 rounded-2xl border border-slate-800 bg-slate-900 space-y-3">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-mono font-bold text-indigo-400">{b.code}</span>
                  <span className="text-slate-400">{b.fiscalYear}</span>
                </div>

                <h3 className="text-sm font-bold text-white">{b.name}</h3>
                <div className="text-[11px] text-slate-500">Category: {b.category}</div>

                <div className="pt-2">
                  <div className="flex justify-between text-xs font-semibold mb-1">
                    <span className="text-slate-400">Total Allocated</span>
                    <span className="text-white font-mono">{formatCurrency(b.allocatedAmount)}</span>
                  </div>

                  <div className="w-full bg-slate-950 h-2 rounded-full overflow-hidden flex border border-slate-800">
                    <div className="bg-indigo-500 h-full" style={{ width: `${spentPct}%` }} />
                    <div className="bg-amber-500 h-full" style={{ width: `${committedPct}%` }} />
                  </div>

                  <div className="flex justify-between text-[11px] text-slate-500 mt-2">
                    <span>Spent: {spentPct}%</span>
                    <span>Committed: {committedPct}%</span>
                  </div>
                </div>

                <div className="pt-2 border-t border-slate-800 flex justify-between text-xs">
                  <span className="text-slate-400">Remaining Liquidity:</span>
                  <span className="font-bold text-emerald-400">{formatCurrency(b.remainingAmount)}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* DISBURSEMENT / PAYMENT MODAL */}
      {payModalInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="w-full max-w-md rounded-2xl bg-slate-900 border border-slate-800 p-6 shadow-2xl text-left">
            <h3 className="text-sm font-bold text-white">Release Payment for {payModalInvoice.invoiceNumber}</h3>
            <p className="text-xs text-slate-400 mt-1">
              Recipient: <strong className="text-white">{payModalInvoice.vendorName}</strong>
            </p>

            <div className="my-4 p-4 rounded-xl bg-slate-950 border border-slate-800 text-center">
              <span className="text-xs text-slate-400">Total Settlement Value</span>
              <div className="text-2xl font-black text-white mt-0.5">
                {formatCurrency(payModalInvoice.totalAmount)}
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Payment Channel</label>
                <select
                  value={payMethod}
                  onChange={(e) => setPayMethod(e.target.value as any)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white"
                >
                  <option value="bank_transfer">Direct Corporate Wire / SWIFT</option>
                  <option value="credit_card">Corporate Purchasing Card</option>
                  <option value="check">Certified Commercial Bank Draft</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Transaction Reference</label>
                <input
                  type="text"
                  value={txnRef}
                  onChange={(e) => setTxnRef(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2 text-xs text-white font-mono"
                />
              </div>
            </div>

            <div className="mt-5 flex justify-end gap-2">
              <button
                onClick={() => setPayModalInvoice(null)}
