                <button
                  type="submit"
                  className="px-6 py-2 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-bold text-xs"
                >
                  Run 3-Way Match & Submit
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

